import"./modulepreload-polyfill-B5Qt9EMX.js";import{d as w,h as K,s as V,i as Y,u as _}from"./site-translations-vK9rWEuP.js";const e=(t,o,n)=>`<section aria-labelledby="${t}"><h2 id="${t}">${o}</h2>${n}</section>`,i=t=>`<ol class="doc-steps">${t.map(o=>`<li>${o}</li>`).join("")}</ol>`,b=t=>`<ul>${t.map(o=>`<li>${o}</li>`).join("")}</ul>`,P=(t,o)=>`<aside class="doc-note"><strong>${t}</strong><p>${o}</p></aside>`,c=(t,o)=>`<div class="doc-table" data-columns="${t.length}"><table><thead><tr>${t.map(n=>`<th scope="col">${n}</th>`).join("")}</tr></thead><tbody>${o.map(n=>`<tr>${n.map(a=>`<td>${a}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`,H=["开始使用","核心工作流","桌面与扩展","帮助与参考"],Q=[{id:"welcome",group:"开始使用",title:"认识 EchoBird",summary:"先分清应用、账号、模型与接入方案，找到适合自己的使用路线。",body:['<p class="doc-lead">EchoBird 把 AI 工具、账号和模型放到一个桌面里。你可以继续使用熟悉的客户端，在这里完成准备、切换与管理，再把注意力放回真正想做的事。</p>',e("what-it-does","先看懂这四个概念",c(["概念","可以把它理解成","在 EchoBird 哪里管理"],[["应用 / Agent","真正执行任务或与你对话的工具，例如编程客户端、桌面助手","应用桌面"],["账号","你在服务商那里登录的身份，以及它对应的套餐、授权与额度","账号中心"],["模型","一条可调用的 API 配置：地址、凭据和模型 ID","模型中心"],["智能接入方案","把多个可用来源组织起来，为工具提供一个本地入口","智能接入"]])),e("choose-path","你可以从哪条路开始",b(["<strong>已经有官方账号：</strong>先识别或安装应用，再添加账号，在应用桌面中选择并应用。适合沿用现有订阅的人。","<strong>已经有 API Key：</strong>先在模型中心保存配置、测试速度，再到支持的工具验证模型回复。适合想复用 API 服务的人。","<strong>有多条模型线路：</strong>在智能接入里安排常用与备用来源，让工具连接同一个入口。","<strong>想使用自己的硬件：</strong>先在本地大模型页面启动服务，再让其他支持的功能使用它。"])),e("what-is-different","管理、选择、应用，是不同的步骤",`<p>保存账号或模型，表示 EchoBird 记住了它；选中条目，表示你准备使用它；应用配置，才会把选择落实到对应工具。三者分开，方便你集中维护多份配置，也避免浏览页面时就改动正在工作的客户端。</p>${P("先跑通一个工具","第一次使用建议只选一个已经熟悉的工具。完成一次「保存来源、选择工具、应用配置，再实际发起请求」，再增加账号、备用模型和桌面功能。")}`),e("page-map","整套功能怎样衔接",'<p>应用桌面是入口，账号中心与模型中心提供可用来源，智能接入组织线路，AI 助手执行你提出的任务。语音输入减少打字，用量岛让状态留在桌面，TokenPet 为工作过程增加陪伴。新闻、AI 生涯和本地大模型可以按需要开启。</p><p>先读<a href="#quick-start">第一次使用</a>；已经配置好来源，可以直接看<a href="#workflows">组合使用教程</a>。</p>')].join("")},{id:"quick-start",group:"开始使用",title:"第一次使用",summary:"从安装 EchoBird，到让第一个工具真正工作。",body:[e("install","安装并打开 EchoBird",i(['从<a href="./#download">官网下载区</a>选择与你的操作系统和处理器匹配的安装包。Windows、macOS 和 Linux 的包不能混用。',"完成系统安装流程并打开 EchoBird。首次打开后，先在应用桌面查看哪些工具已经被识别。","已安装但没有出现的工具，先点击刷新，再通过工具路径入口核对可执行文件的位置。"])),e("prepare-source","准备一种可用来源",`<p>以下两条路线任选一条即可，不必为了入门同时配置账号和 API。</p>${c(["你已有的东西","下一步","完成后去哪里"],[["受支持服务的官方账号","进入账号中心，按服务要求添加并完成授权","应用桌面选择对应工具与账号"],["服务商提供的 API Key","进入模型中心，填写真实接口地址和模型 ID，保存后点击「测试速度」","应用桌面选择支持该模型配置的工具"]])}<p>网页聊天账号的密码不是 API Key。同一家厂商的国内、国际、订阅或不同服务入口，也不一定可以共用凭据。</p>`),e("first-launch","完成第一次应用与启动",i(["在应用桌面选中一个已安装的工具。右侧会显示这个工具支持的账号或模型选项。","选择刚刚保存的来源。官方账号与 API 模型互斥：选择其中一种会清除另一种选择。","阅读底部当前主操作以及启动、配置写入选项，按你的目标执行应用或启动。真实客户端的按钮会随情境变化。","进入打开的工具，检查当前身份或模型，并发送一次简单请求，例如「请简要介绍你能做什么」。"])),e("verify","怎样算是配置成功",b(["工具能正常打开，实际请求能得到正常回复。","使用官方账号时，工具中的身份是你期望的账号。","使用 API 时，地址、模型 ID 和凭据匹配；需要路由时，本地接入入口处于可用状态。","失败时保留具体错误。授权、模型 ID、协议、网络与安装路径是不同的问题，应分别处理。"])),e("next","接下来做什么",'<p>想让多个工具复用配置，继续阅读<a href="#models">模型中心</a>；需要备用线路，阅读<a href="#smart-access">智能接入</a>；希望减少手动安装，阅读<a href="#assistant">AI 助手</a>。如果工具已经能用，先保留这条成功配置，再逐步添加新功能。</p>')].join("")},{id:"navigation",group:"开始使用",title:"界面与页面导航",summary:"看懂左侧导航、应用桌面顶部入口和每个页面的主区域。",body:[e("main-navigation","左侧导航负责切换工作区域",c(["页面","主要解决的问题"],[["应用桌面","我现在要打开哪个工具，用哪个来源？"],["模型中心","有哪些可复用的 API 服务和模型配置？"],["账号中心","我的账号、套餐和额度怎么样？"],["智能接入","如何为工具组织模型来源与备用顺序？"],["语音输入","如何配置录音、识别和文字处理？"],["AI 助手","能否直接描述目标，让助手执行任务？"],["新闻 / AI 生涯 / 本地大模型","按需要开启的扩展工作区域"]])),e("desktop-tabs","应用桌面顶部还有这些入口","<p>「我的」查看应用入口，「商店」浏览未安装工具。顶部的「宠物」「插件」「用量岛」分别管理 TokenPet、扩展能力与桌面用量展示，它们不需要你先在应用图标里找一个同名程序。</p><p>智能接入的「配置」与「统计」也有不同职责：前者组织来源，后者观察请求的结果和趋势。</p>"),e("panels","主区域、右侧面板和底部操作怎么看",b(["<strong>主区域：</strong>显示当前页的应用、模型、账号、对话或设置。","<strong>右侧面板：</strong>补充当前选择的配置、来源、目标或详情。换一个工具后，右侧控件可能不同。","<strong>底部主操作：</strong>将当前选择落实为应用配置、启动或安装请求。执行前看清按钮和选项。","<strong>返回与前进：</strong>用于回到之前浏览的位置；这不是撤销已经执行的配置、命令或安装。"])),e("missing-page","找不到某个页面时","<p>先打开左下角设置，检查对应可选页面是否开启。本地大模型还与当前版本包含的能力有关。某个工具没有账号区、Image 或 1M 按钮，通常表示它没有提供这项接入能力，不代表所有页面都缺失了功能。</p><p>页面、按钮与官网首页的交互演示并不完全相同：演示使用示例数据与简化流程，实际操作请以客户端当前界面为准。</p>")].join("")},{id:"apps",group:"核心工作流",title:"应用桌面与商店",summary:"发现工具、安装工具、选择来源，再完成应用配置与启动。",body:[e("desktop","「我的」：把熟悉的工具放在一起","<p>应用桌面展示常用 AI 客户端、CLI 与相关工具。选中图标后，右侧展示这个工具可用的账号与模型配置。工具本身仍是你熟悉的客户端，EchoBird 负责集中管理入口与受支持的配置。</p><p>不是每个工具都支持相同操作。有的能切换官方账号，有的能填写 API 模型，有的主要提供启动入口。先看当前工具实际显示的选项。</p>"),e("discover","已安装却没被识别",i(["确认第三方工具已经完成安装，能在系统里正常启动。","回到 EchoBird 点击刷新，让它重新检测本机工具。","如果仍未识别，打开工具路径配置入口，核对工具可执行文件的位置。","修正后再次刷新。不要把其他项目的启动文件当成这个工具，也不要为了检测成功随意覆盖原有账号配置。"])),e("install-tools","「商店」：从发现到安装",`<p>商店提供未安装工具的分类与入口。选择工具后使用「一键安装」，会进入 AI 助手并预填该工具的安装请求。之后要结合助手输出和你的系统环境继续完成安装。</p>${P("安装并非浏览时自动发生","浏览商店或选中图标不会自动安装软件。安装可能涉及下载、依赖、网络与系统权限；助手完成后，回到应用桌面刷新并实际启动工具，才能确认结果。")}`),e("apply","账号和模型怎样真正用到工具上",i(["选中已安装工具，再选官方账号或 API 模型。两种来源互斥，避免客户端使用冲突的身份和接口。","查看底部是否需要写入配置、是否同时启动。只想配置时按当前工具允许的选项执行。","执行主操作并等待结果。若涉及运行中的客户端或恢复官方接口，以客户端提示处理。","打开对应客户端检查实际身份和模型。右侧高亮表示当前选择，不保证所有已经运行的窗口立即完成切换。"])),e("capabilities","Web Search、Image 与 1M",c(["能力项","含义","需要知道"],[["Web Search","支持工具的联网搜索配置","还取决于模型和服务端能力"],["Image","支持工具的图像输入配置","开启按钮不会让纯文本模型自动获得视觉能力"],["1M","支持工具的大上下文模式","实际上下文、费用与限制由工具及服务决定"]])+"<p>药丸按钮彼此独立，可以分别启用。真实客户端中，部分工具在已有有效 API 配置时会重新应用能力设置；它们并非始终只改变外观。没有出现某个按钮时，以当前工具开放的能力为准。</p>"),e("result","推荐用法",'<p>先保留一个工作正常的官方账号或模型配置，再为常用工具建立清晰的选择习惯。需要多来源与故障切换时，把工具接到<a href="#smart-access">智能接入</a>，而不是每次进入客户端重复改接口地址。</p>')].join("")},{id:"accounts",group:"核心工作流",title:"账号中心",summary:"添加与管理账号，看清套餐、额度、余额和授权状态。",body:[e("account-purpose","先保存账号，再决定用在哪里","<p>账号中心集中展示已接入服务的账号及可取得的用量信息。一个服务可以有多个账号；同一个页面也可以管理不同服务。这里适合比较状态、刷新和维护授权，不等于点击一张卡片就切换了某个外部客户端。</p>"),e("add-account","添加第一个账号",i(["在服务列表找到对应服务，点击添加账号。","按服务要求完成浏览器登录、设备码授权、客户端登录或其他受支持流程。不同服务的步骤与前提可能不同。","等待 EchoBird 保存授权结果。等待中可以取消；超时后重新发起，不要一直等旧流程完成。","确认卡片上的身份，再到应用桌面选择对应应用、账号，执行应用或启动。"])+"<p>部分服务新增登录要求本机已安装客户端。已保存账号能否在客户端未安装时刷新或管理，也取决于接入能力。先看当前入口的提示，不必为了管理现有记录把所有客户端重新安装一遍。</p>"),e("read-quota","怎样阅读额度与余额",c(["展示信息","应该怎样理解"],[["套餐 / Plan","账号的订阅或服务级别，不等于剩余可用量"],["5 小时、周等额度","不同周期的额度桶，分别看百分比与重置时间"],["余额 / 积分","服务商自己的计量单位，不能和其他服务直接相加"],["倒计时","对应周期重置或服务状态的时间参考"],["— 或未知","暂时没有可用数据，不等于零，也不等于无限"]])+"<p>需要最新数据时使用刷新。只进入页面与主动向厂商查询是两件事；授权失效、网络异常或厂商没有开放查询接口，都可能影响结果。</p>"),e("account-actions","卡片上的操作",b(["<strong>刷新 / 刷新全部：</strong>重新取得支持查询的用量信息，不负责为客户端切换账号。","<strong>领取：</strong>只有服务提供这项能力时才出现，可用状态与领取结果以该账号为准。","<strong>预热：</strong>仅适用于提供该操作的接入，不是所有账号都需要预热。","<strong>重新授权：</strong>授权失效后重新走登录流程；先区分授权错误与普通额度查询失败。","<strong>排序与隐私：</strong>把常用账号拖到前面，分享屏幕时隐藏身份。隐藏显示不会清除授权。","<strong>删除：</strong>按确认流程移除 EchoBird 保存的账号记录，不是注销厂商账号或取消订阅。"])),e("account-example","一个多账号工作习惯","<p>工作前刷新常用账号，分别查看正确的周期额度；在应用桌面为目标工具选择一个账号并应用。需要备用 API 时到模型中心准备独立配置。不要把多个账号的订阅额度误认为能直接合并给所有模型使用。</p>")].join("")},{id:"models",group:"核心工作流",title:"模型中心",summary:"整理 API 地址、密钥和模型 ID，先测试，再把模型用于工具。",body:[e("model-fields","四个字段，分别填什么",c(["字段","用途","例子或注意事项"],[["名称","方便自己辨认配置","如「日常写作」「备用编程」，不必等于模型 ID"],["接口地址","服务实际提供的 API 入口","区分 OpenAI 兼容、Anthropic 兼容与不同地区入口"],["API Key","调用服务的凭据","从服务商获取，不是网页登录密码"],["模型 ID","服务实际接受的模型标识","尽量从当前服务返回的模型列表选择，不凭产品昵称猜测"]])),e("save-model","添加与验证模型",i(["打开模型中心，从模型提供商或中转站目录选择服务，或按当前表单入口填写自己的服务。","核对地区、套餐和协议版本；同一家公司的订阅接口与通用 API 接口不一定通用。","填写真实地址和密钥。支持发现模型列表的服务可获取候选 ID；其他服务按其实际说明填写。","设置便于识别的名称并保存。在配置视图顶部点击「测试速度」，检查服务地址的连接状态与延迟。","随后到应用桌面选择支持的工具并应用，或把它加入智能接入方案；在真实工具或 AI 助手里发送请求，验证模型回复。"])),e("test-vs-usage","测试速度、验证回复、查询用量，分别看什么","<p>配置视图顶部的「测试速度」检查服务地址的连接与延迟，不是聊天测试，也不能单凭它确认 API Key、模型 ID 或回复内容都正常。要验证模型，需到真实工具或 AI 助手发送请求；用量视图则用于查询服务能提供的余额或额度。</p><p>实际模型请求可能按服务商规则计费。模型能回复，也不代表服务开放余额 API；部分用量查询需要额外配置或授权，查询失败不能直接证明模型不可用。</p>"),e("maintain-models","编辑、排序与删除","<p>把常用配置放在前面，用清楚的名称区分工作、日常和备用来源。修改后再次验证地址、模型 ID 与凭据是否匹配，再确认目标工具使用的是你期望的配置。</p><p>删除本地条目并不会删除服务商账号或远程撤销 API Key。更换或撤销密钥应到对应服务商处理，再回来更新需要使用它的配置。</p>"),e("saved-not-applied","最常见的误区：保存之后工具没有变化","<p>模型中心是配置库。保存成功只表示条目已经建立，不会自动把所有外部客户端改成这个模型。接下来要在应用桌面选中工具并应用，或在智能接入中引用它，再让工具连接该方案。</p><p>接口兼容也不是所有能力都相同：工具调用、图片输入、上下文与模型参数，还需当前工具、模型和接入适配共同支持。</p>")].join("")},{id:"smart-access",group:"核心工作流",title:"智能接入",summary:"组织多个模型与账号来源，实时选模型，为客户端保留一个稳定入口。",body:['<p class="doc-lead">智能接入把模型选择留在你手里：客户端连接一个本地入口，你在 EchoBird 中管理后面的来源、模型 ID 与尝试顺序。</p>',e("routing-model","一个方案，一条有顺序的线路","<p>方案中的编号表示优先级。请求先尝试靠前的来源；限流、额度耗尽或临时不可用时，再尝试后面的来源。冷却结束后会恢复按优先级尝试。</p><p>这与同时请求多个模型不同，也不会把不同厂商的额度合并。来源能否使用、能够访问哪些模型，仍由它自己的授权、套餐和服务能力决定。</p>"),e("create-route","建立你的第一个方案",i(["进入智能接入，从「我的模型」「账号接入」或「免费模型」选择来源。已经保存在模型中心的配置可以直接引用。","给方案取清楚的名字，核对它使用的本地端口、接入密钥与模型标识。端口应未被占用，使用当前界面实际显示的地址。","把最常用的模型放在前面，备用来源放在后面；拖动调整后会自动保存，从下一次请求生效，不会中途替换正在回答的模型。","展开来源的模型选择器，选择它真实可用的模型 ID。必要时先获取或刷新服务提供的列表。","到应用桌面选择支持模型切换的工具，选择这个方案并执行配置应用。","在工具里发起一次真实请求，再看接入状态与统计，确认请求已走到期望来源。"])),e("source-labels","免费与免密钥有什么区别",c(["标记","表达的含义","不代表什么"],[["免费","该目录中的具体模型选项标为免费","该供应商全部模型都免费、无限量或永久可用"],["免密钥","该入口不要求你自己填写 API Key","它一定没有限流、没有条件或适合所有任务"],["账号接入","使用账号接入所提供的模型目录和授权","任何订阅账号都能调用所有厂商的模型"]])),e("route-views","卡片、列表与终端","<p>卡片适合观察来源与选择模型 ID；列表便于排序、启用或暂停条目；终端可以观察编组请求信息。若终端明确提示当前为示意数据，它不代表你已经产生了真实请求或费用。</p><p>从方案中移除一个来源，只移除这份引用，原始模型或账号仍保留。删除方案后，如果外部工具还指向原地址，应主动改成其他可用入口。</p>"),e("route-endpoints","OpenAI 与 Anthropic 地址怎么用",`<p>方案会提供本机 OpenAI 兼容和 Anthropic 兼容入口，供不同客户端使用。复制当前方案显示的地址与密钥，不要根据示例端口猜地址，也不要手动把一个协议地址的后缀改成另一个协议。</p>${P("使用本地入口时，让 EchoBird 保持运行","完全退出 EchoBird 后，本地接入地址不可用。最小化到托盘与退出应用不同；如果工具突然连不上，先检查 EchoBird 是否仍运行、方案和端口是否正确。")}`),e("route-workflow","实际效果：保持入口，调整来源","<p>例如，为编程工具建立「日常编程」方案：首选模型负责常规任务，另一家可用服务作为备用，再按需要加入符合要求的免费来源。工作中调整后方模型和顺序，比在每个客户端反复改接口更集中。仍要检查重要任务的输出，备用切换不能保证所有模型质量相同。</p>")].join("")},{id:"statistics",group:"核心工作流",title:"请求统计",summary:"观察调用、完成率、故障切换和耗时，定位线路问题。",body:[e("open-statistics","在哪里看统计","<p>在智能接入顶部进入统计页面。可以按今天、7 天、14 天等时间范围，以及全部或具体接入方案观察数据。工作中先让工具产生真实请求，再回来看，才容易理解每项指标。</p>"),e("statistics-metrics","怎样理解这些数字",c(["指标","解读方式"],[["调用次数","客户端发起的请求，不应直接等同于上游尝试次数"],["完成率","基于已有成功或失败结果的请求计算"],["故障转移成功","某次请求更换上游后最终成功，不代表每次尝试都成功"],["平均耗时与趋势","帮助比较所选时间范围内的实际表现"],["来源分布与最近使用","观察请求主要落在哪些来源以及最近活动"]])),e("statistics-debug","发现异常时怎么排查",i(["先核对当前选择的时间范围和方案，避免在错误范围里查找请求。","观察失败来源与切换结果：首选来源失败、备用最终成功，和整次请求失败是不同情况。","回到智能接入确认该来源的模型 ID、启用状态与优先级。","需要时在账号或模型中心明确刷新状态、测试服务，再重新发送请求验证。"])),e("statistics-limits","统计和账单并非同一件事","<p>这里用于了解经过接入的请求情况，不是所有厂商的完整账单，也不是精确扣费系统。未记录到请求不代表账号余额为零，尝试次数也不能直接当作付费次数。</p><p>设置中的统计记录开关、本机存储状态和所选范围都会影响可见数据。分享统计页面前，可以隐藏账号名称，避免展示真实身份。</p>")].join("")},{id:"assistant",group:"核心工作流",title:"AI 助手",summary:"描述目标，让助手检查环境、安装工具或执行实际任务。",body:[e("assistant-first","先准备可用模型，再开始对话",i(["进入 AI 助手，普通对话模式先选择一个已经配置且可工作的模型。","确认任务目标是本机，还是右侧已添加的 SSH 服务器。目标决定之后操作的上下文。","写清楚要做什么、涉及哪个工具、希望达到什么结果。必要时附上具体报错。","发送后观察工作状态、工具调用与返回结果。工具卡片可以展开查看参数和输出。"])),e("assistant-prompts","比「帮我弄一下」更有效的请求",b(["「检查本机 Claude Code 的安装和启动环境，先告诉我发现的问题。」","「帮我安装 Git，完成后检查终端里能否使用。」","「这个工具启动时报错：……。请检查原因，并说明修复了哪些地方。」","「查看这台机器的硬件配置，说明适合怎样的本地模型。」"])+"<p>助手会结合模型、任务与环境决定步骤。官网动画中的找线路、装环境、配 PATH 是示例，不是所有任务都必须按同一个流水线执行。</p>"),e("assistant-progress","怎样确认它做了什么","<p>AI 助手具备真实命令与文件操作能力。查看工具输出，比只看最终总结更容易判断安装是否完成、文件改在哪里、错误是否消除。安装后回应用桌面刷新检测，并实际启动工具验证。</p><p>任务运行中可以停止；停止不等于撤销已经执行的命令。不同任务也不一定每一步都会弹出确认，因此先明确目标和允许处理的范围，不要把不明命令与凭据随意粘贴给助手。</p>"),e("assistant-conversations","对话与本轮设置","<p>可以新建、切换和删除对话，按项目或任务分开管理。删除对话有确认，但不会因此卸载已经安装的工具。模型、推理强度等参数通常在发送时确定；进行中的任务以本轮已提交的设置为准，之后的调整主要影响下一轮。</p>"),e("assistant-connect","连接现有 Agent：Connect","<p>当前连接模式支持已安装的 Claude Code CLI。进入此模式后，本轮交给 Claude Code 自己的环境、工具、记忆和模型配置，EchoBird 的模型选择器会隐藏。</p><p>想改它的模型，需要在应用桌面或 Claude Code 自己的配置中管理。不要把普通助手模式的模型选择方式直接套到连接模式上。</p>"),e("assistant-ssh","把任务交给自己的服务器","<p>右侧可以添加 SSH 服务器，填写主机、端口、用户名与相应认证信息，先测试连接，再选择它执行任务。远程机器必须已经有可访问的 SSH 服务；这不会替你购买或创建云服务器。</p><p>服务器删除只移除保存的连接条目，远程软件不会因此自动卸载。涉及系统权限时，按实际提示操作；本机需要密码的步骤可能交还原生终端完成。</p>")].join("")},{id:"voice",group:"桌面与扩展",title:"语音输入与划词",summary:"配置识别通道、麦克风与快捷键，把口述内容送回输入框。",body:[e("voice-setup","先把一条语音通道跑通",i(["进入语音输入，添加一个受支持的账号来源，或配置单独的语音识别 API 模型。普通聊天模型不一定支持语音识别。","核对语音 API 地址、模型与授权。最多可以设置三个不同通道，第一条主用，后面的备用；拖动可以调整顺序。","选择默认或指定麦克风，点击测试，观察音量是否随说话变化。测试完成后停止。","先识别一句短句，确认文字正常，再设置不与常用软件冲突的快捷键。"])),e("voice-use","在正在工作的输入框里使用",i(["先把光标放在聊天框、编辑器或其他可输入位置。","通过话筒或快捷键开始录音。快捷键可选择长按或点按的输入方式。","结束录音后等待识别与输入完成，检查回填文字，再决定是否发送。","如果焦点变化或系统不允许回填，复制保留的识别结果，再手动粘贴；需要时可以回听录音。"])),e("voice-island","语音岛显示什么","<p>语音岛展示录音、识别、回填与完成状态。可以按桌面习惯调整主题、配色和大小。它与用量岛是不同的功能：语音岛围绕输入过程，用量岛围绕账号和模型用量。</p>"),e("selection","划词翻译与提问","<p>先配置可用的文本模型，再开启划词翻译或提问。选中文字后，可在选区附近发起操作并选择翻译目标语言。单次选中文字上限为 16000 字符，长文可以分段。</p><p>系统无法取得选中文字时，可以先复制，再用粘贴并翻译。失败时原文保留，可以重试；没有配置文本模型时，不会自动得到翻译结果。</p>"),e("voice-permissions","没有声音、快捷键无效或不能回填",b(["麦克风没有音量：先检查选中的设备、系统输入音量与麦克风权限。","快捷键无效：检查按键冲突和系统键盘监听权限。macOS 回填还可能需要辅助功能权限。","Linux / Wayland：快捷键、选区和回填取决于桌面的 portal 或桥接支持，按实际环境配置。","识别请求失败：核对通道的服务类型、地址、凭据与网络。远程语音 API 不是完全离线识别。"])),e("voice-workflow","推荐组合","<p>在 AI 助手的输入框放好光标，口述完整任务，检查识别文字后再发送；阅读外语资料时先划词翻译，再把已经理解的要求交给助手。语音输入负责减少打字，发送前的检查仍能帮助你避免错词改变任务含义。</p>")].join("")},{id:"usage-island",group:"桌面与扩展",title:"用量岛",summary:"让用量显示就在桌面，按自己的习惯选择五种形态。",body:[e("island-purpose","哪些信息适合放在桌面","<p>用量岛将常用账号的剩余额度、重置倒计时，或 API 模型余额收进小型桌面浮窗。工作时可以快速扫一眼，不必反复回到管理页。它负责显示状态，不会增加额度，也不会自动替所有工具切换账号。</p>"),e("island-setup","第一次配置",i(["在应用桌面顶部进入用量岛。先在账号中心或模型中心准备可用来源。","选择希望显示的账号或模型，最多六个。优先放最常用、最容易耗尽额度的来源。","选择外形与展开方向，再选择悬停、点击展开或常开。","按桌面背景调整主题、大小和透明度，再启用用量岛。","需要新数据时主动刷新，或根据需求设置刷新间隔。"])),e("island-shapes","五种形态怎么选",c(["形态","适合怎样摆放","展开方向"],[["横向","屏幕边缘或宽一些的空位","向左 / 向右"],["上下","侧边窄区域","向上 / 向下"],["圆盘","紧凑地集中显示多个来源","顺时针 / 逆时针"],["列表","希望逐项阅读状态","按列表组织信息"],["线条","低占用的横向概览","按所选方向展开"]])+"<p>形态和方向只改变展示方式，不会改变账号权限、模型能力或路由顺序。</p>"),e("island-controls","主题、大小、透明度与刷新","<p>主题支持主题色、深色、浅色或跟随；大小范围为 70%–150%，透明度范围为 20%–100%。字太小可以先增加大小，再调整摆放位置。</p><p>默认使用手动刷新，也可以选择 5、15、30 或 60 分钟。来源是否支持刷新、能提供哪些字段，仍由对应接入决定。未知值不能当作零余额。</p><p>开启智能接入状态后，可以观察当前接入活动；它是状态展示，不是创建了另一条线路。</p>"),e("island-scenario","与智能接入一起用","<p>先建立日常接入方案，再把常用账号或模型加入用量岛。看到额度将尽时，回到对应页面刷新并核对，再调整来源或优先级。用量岛帮你发现需要关注的状态，账号与模型的真实应用操作仍在相应页面完成。</p>")].join("")},{id:"pets",group:"桌面与扩展",title:"宠物与 TokenPet",summary:"把经过智能接入记录的 Token 转为宠物成长，了解孵化、升级和补给。",body:[e("pet-entry","从一只宠物开始","<p>在应用桌面顶部进入宠物。当前有铁豆豆、彩虹独角兽、背鳍巨兽、九尾狐、外星人、袋鼠先生六种体素宠物，以及不同配色。你可以选择宠物、拖动旋转，或用方向键调整视角。</p><p>TokenPet 是宠物系统内的成长单位。它不等于 API 余额，不是可以提现的货币，也不会替服务商增加可用额度。</p>"),e("tokenpet-source","TokenPet 从哪里来",`<p>当前系统根据智能接入账本记录的 Token 消耗累计量，按新增部分转入宠物成长余额，避免同一份累计量重复入账。需要在设置中开启「记录统计」，并且上游响应提供可识别的用量数据。</p>${P("只看可记录的接入用量","并非你所有网页、所有第三方工具或账号的消费都会被监测和兑换。没有经过智能接入，或没有对应可用记录的消费，不一定会产生 TokenPet。无需为了完成新手教程额外消耗模型 Token。")}`),e("pet-grow","孵化与升级怎么操作",i(["查看 TokenPet 余额，选择你想培养的宠物。","点击升级，把可用余额投入成长。余额不足以一次完成整级时，可以累计本级经验。","等待升级与阶段动画完成，再进行下一次操作。观察宠物从蛋、裂壳到幼体和成体的变化。","需要培养更多宠物时，可以按页面显示的价格购买新蛋。当前新蛋为一亿 TokenPet，价格和升级成本以界面显示为准。"])),e("pet-stages","成长阶段",c(["等级","形态"],[["0–9","完整蛋"],["10–19","裂壳蛋"],["20–29","幼体"],["30–49","成长体"],["50–60","成体；当前满级为 60"]])),e("pet-rewards","宠物补给分别有什么作用",b(["<strong>成长卡：</strong>增加宠物系统中的 TokenPet。","<strong>双倍卡：</strong>影响成长卡收益，当前时长为 15 分钟；不是双倍模型额度。","<strong>加速卡：</strong>让下一次补给更早，不会加速模型推理。"])+"<p>是否可以领取以及下一次补给时间，看页面倒计时。宠物是工作之外的陪伴体验，不是使用应用、模型或智能接入的前置条件。</p>")].join("")},{id:"plugins",group:"桌面与扩展",title:"插件",summary:"发现和管理扩展，理解安装来源、权限与更新。",body:[e("plugin-entry","插件解决什么问题","<p>应用桌面顶部的插件页用于发现和管理扩展。插件可以提供应用入口、账号接入、外观或其他功能。它与安装一个第三方 AI 客户端不同：客户端是你使用的工具，插件是在 EchoBird 内补充受支持能力。</p>"),e("plugin-find","从目录里找扩展",i(["打开插件页，在目录与已安装内容之间查看你需要的扩展。","用搜索或分类缩小范围，例如应用、账号、外观、功能等。","需要时切换国际、国内或 CNB 来源。刷新失败时先检查所选来源，已安装列表与在线目录并非同一份数据。","选中扩展，阅读右侧名称、描述、来源、版本与权限，再按当前安装入口操作。"])),e("plugin-import","从仓库或本地目录添加","<p>添加菜单提供仓库和本地目录入口。使用你确认来源的地址或扩展目录，等待候选扩展信息解析，再阅读权限并完成安装。不是任意文件夹都能成为有效插件。</p><p>账号插件涉及授权接入，模型请求权限可能让插件使用模型；剪贴板、配置、存储、命令或后台能力也各有用途。根据你要使用的功能核对权限，不要只看插件名字相似就安装。</p>"),e("plugin-manage","启用、更新与卸载","<p>安装后根据插件提供的控制项启用和使用。右侧可以检查更新；若新版新增权限，需要重新确认。取消确认时，不等于已经完成更新。</p><p>卸载有确认流程。扩展移除之后，对应账号能力或界面入口可能不可用；保留下来的缓存展示不表示该服务仍能继续执行操作。遇到更新失败，先检查来源、网络和具体错误，再重试。</p>"),e("plugin-account-use","想添加的账号服务不在列表里","<p>先检查该服务是否通过账号插件提供，以及插件是否已安装和启用。完成后回账号中心或对应工具页面查看。插件能增加接入方式，但不能绕过厂商登录、权限与套餐限制。</p>")].join("")},{id:"news",group:"桌面与扩展",title:"AI 动态",summary:"按日期集中阅读资讯，在需要时回到原文。",body:[e("news-read","阅读当前日期的资讯",i(["从侧栏进入 AI 动态，等待内容加载。","简体中文界面可以在国内和全球来源之间切换；其他界面语言使用全球来源。","通过右侧日期树选择日期，列表展示所选日期的内容。","查看标题、来源与相对时间；点击具体条目后打开原始文章。"])),e("news-refresh","刷新与历史缓存","<p>需要新内容时使用刷新。网络失败时，已有缓存会保留，不必为了重新加载立刻清空历史或重装。查看过去内容时，也要核对当前来源和日期，避免以为历史数据全部消失。</p>"),e("news-purpose","把阅读和执行分开","<p>AI 动态帮助你集中获取消息，原始内容与观点来自对应来源。看到一个新工具后，可以再到应用桌面确认是否收录；想试用前，核对它的实际系统要求和官网说明。阅读资讯不会自动安装工具，也不会自动让助手执行文章中的命令。</p><p>如果不需要资讯入口，可以在设置中关闭 AI 动态，保留更简洁的侧栏。</p>")].join("")},{id:"career",group:"桌面与扩展",title:"AI 生涯",summary:"回顾本地会话、活跃记录和使用节奏，找回可继续的工作。",body:[e("career-overview","总览里能看到什么","<p>AI 生涯整理受支持工具的本地会话和活动记录。总览包含会话数、消息数、约累计 Token、活跃天数与最长连续天数，并通过贡献热图和日活动图展示使用节奏。</p><p>这些数据的可用字段因工具而异。Token 包含估算口径，不能直接当作服务商账单；没有记录，也不一定表示你从未用过某个工具。</p>"),e("career-find","找回一个会话",i(["打开 AI 生涯，等待本地记录加载，先按日期观察活动趋势。","选择工具家族，查看对应的会话列表。","找到目标会话，检查时间、内容摘要以及可用的项目路径或会话信息。","按该工具提供的操作复制会话 ID、恢复命令或项目路径，也可以定位记录文件。","回到对应工具继续工作。并非每种工具、每个会话都提供完全相同的恢复能力。"])),e("career-combine","它与其他页面怎样搭配","<p>应用桌面帮你打开工具，AI 生涯帮你回顾在工具中的活动。重新开始一项工作时，先找回会话和项目路径，再用应用桌面确认账号与模型来源，能减少从头复述上下文。</p><p>这里围绕本地会话和活动记录，不是多人任务看板。项目路径是会话的相关信息，复制路径不会自动迁移或备份整个项目。</p>")].join("")},{id:"local-models",group:"核心工作流",title:"本地大模型",summary:"下载或扫描模型文件，准备运行引擎，再启动自己的模型服务。",body:[e("local-entry","先分清模型文件与引擎","<p>本地大模型页面管理模型文件、推理引擎和服务进程。它属于完整版本，并受设置中的可选页面开关控制。</p><p>模型文件是权重，运行引擎负责加载并提供服务。下载完成不等于服务已经启动，装好引擎也不等于已经下载模型。常见本地文件使用 GGUF 格式。</p>"),e("local-run","从第一个本地模型开始",i(["在商店查看模型和硬件参考，选择适合这台机器的量化版本；已经有文件时，在本地添加模型目录并扫描。","选择运行时，检测并安装对应引擎。需要时通过已有入口选择版本或升级。","选择模型、端口、算力与上下文长度。先用保守配置跑通，再调整模型规模和上下文。","点击启动，等待输出并核对服务状态、地址与访问密钥。失败时先看日志，不要连续重复启动。","服务正常后，再让 AI 助手或其他支持的模型入口使用它。","不使用时点击停止，释放运行服务占用的资源。离开页面不等于停止服务。"])),e("local-platform","系统与运行时怎么选",c(["运行路径","适用情况"],[["llama.cpp","三平台基础运行路径；性能取决于硬件和构建"],["macOS Metal","可利用相应 Apple 硬件加速"],["NVIDIA CUDA","使用受支持的 NVIDIA 环境和对应构建"],["CPU","没有合适 GPU 时的基础路径，速度取决于模型与硬件"],["vLLM / SGLang","当前界面仅在 Linux 且检测到 NVIDIA / AMD GPU 时提供相应选项"]])+"<p>更长上下文、更大模型通常需要更多内存。给系统和其他工作程序留出空间，比只看模型文件大小更稳妥。</p>"),e("local-files","目录、模型与自定义命令","<p>移除扫描目录，只是从目录列表中移除，不会删除磁盘上的模型文件。下载完成后可以重新扫描。</p><p>高级用户可设置自定义引擎路径和启动参数。第一次使用先保留能工作的默认流程，不要同时改未知参数、端口和模型格式，否则难以确定失败来源。</p>"),e("local-use","与 AI 助手组合","<p>先确认本地服务成功，再在助手里选择可用模型来源。模型运行与任务执行分成两步，便于排查：找不到模型先看文件与扫描，连不上先看进程、端口和密钥，内存不足先减小模型或上下文。</p><p>推理在本机运行，不代表所有任务都离线。助手下载依赖、访问网页或调用外部服务时，仍可能使用网络。</p>")].join("")},{id:"settings",group:"帮助与参考",title:"设置与个性化",summary:"调整界面、语言、页面开关，以及与日常使用相关的行为。",body:[e("settings-entry","在哪里打开设置","<p>从侧栏底部的设置入口打开。设置按常规、外观和语言组织；调整前先确认你要改的是整个应用，还是某个功能自己的设置。</p>"),e("settings-general","常规设置",c(["项目","作用"],[["界面缩放","根据屏幕和阅读习惯调整界面大小，可先试自动缩放"],["关闭窗口行为","选择直接关闭、最小化到托盘或每次询问"],["开机启动","控制系统登录后是否启动 EchoBird"],["自动领取","管理支持的自动领取能力，不等于所有服务都有奖励"],["敏感信息保护","使用智能接入时识别并增强密钥、Token、密码等信息防护；相关映射在本机保存"],["记录统计","控制统计记录，不等于停止已经运行的模型服务"],["可选页面","按需要显示 AI 动态、AI 生涯和本地大模型"]])),e("settings-appearance","外观与背景","<p>选择配色，以及浅色、深色或跟随系统。背景有无背景、字符流、碳纤维、碳岩等选项，可以按桌面和阅读习惯搭配。界面文字偏小时，优先调整界面缩放，不必改变系统分辨率。</p><p>用量岛、语音岛还有各自的主题与大小设置。主窗口外观改变，不等于它们所有参数都会自动改成同一值。</p>"),e("settings-language","语言","<p>当前提供 English、简体中文、繁體中文和日本語。选择后以实际界面更新为准。服务商返回的模型 ID、错误或第三方内容，可能保留原始语言；模型 ID 也不应为了翻译而任意改写。</p>"),e("settings-optional","找不到入口，先检查这里","<p>不需要新闻或活动回顾时，可以关闭相应页面；之后也可以重新打开。本地大模型还要看当前发行版本是否包含该能力。</p><p>用量岛的桌面启用与来源在用量岛页管理；语音输入要先有可用通道。不要把页面显示开关、功能启用开关和服务运行状态混为一谈。</p>")].join("")},{id:"workflows",group:"帮助与参考",title:"组合使用教程",summary:"把独立页面连成真正可用的工作流，理解每一步带来的效果。",body:[e("workflow-account","路线一：沿用现有订阅",i(["<strong>应用桌面：</strong>识别或安装你习惯的客户端。","<strong>账号中心：</strong>添加官方账号，核对身份与授权。","<strong>应用桌面：</strong>选择客户端、选择账号，再执行应用与启动。","<strong>真实客户端：</strong>检查身份并发起请求；需要时回账号中心刷新额度。"])+"<p><strong>得到的效果：</strong>账号状态集中管理，工具仍按熟悉的方式使用。添加账号和切换客户端有明确分工。</p>"),e("workflow-api","路线二：多个工具，复用模型",i(["<strong>模型中心：</strong>保存服务地址、Key 和模型 ID，点击「测试速度」检查连接与延迟。","<strong>应用桌面：</strong>为支持的工具选择这条模型并应用配置。","<strong>第二个工具：</strong>复用同一模型条目，按它支持的协议应用。","<strong>验证：</strong>分别在工具里请求，确认不是只在 EchoBird 保存了配置。"])+"<p><strong>得到的效果：</strong>减少重复输入，保留清楚的模型来源。协议和能力仍以每个工具及模型的支持情况为准。</p>"),e("workflow-route","路线三：常用模型与备用线路",i(["在模型中心验证首选和备用 API，也可以准备受支持的账号来源。","在智能接入创建方案，设置实际入口与密钥，按优先级安排来源。","把编程客户端接入该方案，发起真实请求。","在统计中观察完成与切换结果；把常用用量加入用量岛。"])+"<p><strong>得到的效果：</strong>客户端连接相对稳定，来源可以集中调整。看到额度或失败变化时，有状态信息可帮助判断下一步，而不是盲目重复请求。</p>"),e("workflow-install","路线四：从报错到继续工作",i(["在应用桌面确认安装状态，保留无法启动时的具体错误。","进入 AI 助手，说明工具名、系统、错误和期望结果。","观察环境检查和工具输出，必要时按系统提示处理权限。","回应用桌面刷新检测并实际启动，再确认问题已经解决。"])+"<p><strong>得到的效果：</strong>把安装排障和实际验收连起来。助手的总结帮助理解过程，真实启动结果用来确认效果。</p>"),e("workflow-voice","路线五：口述需求，保持专注","<p>先在语音输入配置通道并测试麦克风，再把光标放到 AI 助手或你常用的工具里。口述任务、检查识别文字、发送。工作时用用量岛观察状态；经过智能接入记录的 Token，也可以在宠物页转为成长体验。</p>"),e("workflow-local","路线六：自己的硬件，自己的模型服务","<p>本地大模型准备文件与引擎并启动服务，再让支持的模型入口和 AI 助手使用它。遇到问题先分清是服务没启动、模型不可用，还是任务本身失败。这样能把「运行模型」和「让模型做事」分别验证。</p>")].join("")},{id:"support",group:"帮助与参考",title:"意见反馈与更新日志",summary:"收集有用信息、选择反馈渠道，并了解每次更新发生了什么。",body:[e("support-entry","进入意见反馈","<p>点击客户端标题栏的意见反馈，或通过系统菜单进入对应页面。这里帮助你准备反馈信息、选择外部提交渠道，不是一个会自动上传所有内容的工单表单。</p>"),e("support-submit","反馈一个问题",i(["先记录系统与架构、EchoBird 版本、页面和工具名，以及触发问题的步骤。","需要排查错误时，点击复制最近 30 条日志。复制不等于已经发送，日志仍需要你在反馈页面中粘贴。","通过页面提供的 GitHub 入口创建 Issue；简体中文界面还提供 Gitcode 反馈入口。","描述预期结果和实际结果，附上必要截图或日志，提交前检查账号、密钥和其他敏感内容。"])+"<p>其他界面语言还提供邮箱按钮，点击会复制 hi@echobird.ai；这一步不会自动发送邮件。你可以在自己的邮件工具中继续联系。</p>"),e("support-suggest","推荐应用或提出建议","<p>同样可以通过外部反馈入口描述希望接入的工具或想改善的流程。写清楚工具名称、官方地址、使用场景，以及你当前需要手动完成哪些步骤，通常比只写“希望支持”更容易理解。功能建议不必为了提交而先复制错误日志。</p>"),e("changelog","更新日志与安装更新的区别","<p>标题栏的更新日志打开版本说明弹窗，展示版本、发布日期和相应语言的变更说明。首次安装或升级到尚未读过的版本时，也可能自动打开一次。</p><p>打开版本说明不会立即安装更新。需要更新软件时，按客户端提供的下载或安装入口继续操作。读取版本说明失败时，可以稍后重试；已有加载内容会尽量保留。</p>")].join("")},{id:"troubleshooting",group:"帮助与参考",title:"常见问题与排查",summary:"先找到问题发生在哪一层，再做对应的检查。",body:[e("issue-account","账号添加成功，客户端却没切换","<p>添加只负责保存。回到应用桌面选中对应客户端与账号，执行当前主操作，并检查运行中的客户端是否需要处理。不要只根据右侧高亮判断所有窗口已完成切换。</p>"),e("issue-model","模型保存了，工具还是旧模型","<p>检查是否在应用桌面应用了该模型，工具是否支持对应协议，以及配置写入选项是否允许操作。先在模型中心点击「测试速度」检查连接，再在真实工具或 AI 助手发送请求，验证回复和实际配置，比重复保存同一条目更有效。</p>"),e("issue-network","模型连不上或路由请求失败",i(["直接模型：核对地址、Key、模型 ID 和服务的地区/套餐入口。","智能接入：确认 EchoBird 仍在运行，工具指向当前方案显示的地址与密钥。","检查来源授权、启用状态与模型目录，区分一个上游失败和最终请求失败。","在对应页面明确测试或刷新，再发一次实际请求；保留错误原文。"])),e("issue-quota","余额或额度为什么是空的","<p>服务能回答请求，不等于开放了用量查询。有些来源需要额外用量配置，有些只提供部分指标。使用明确刷新，并检查授权和服务说明；未知值不等于零。不同周期和计量单位也不能直接相加。</p>"),e("issue-install","安装失败或工具没被识别","<p>先确认厂商支持当前系统和架构，再检查网络、权限、依赖与安装输出。安装完成后回应用桌面刷新；仍未识别时核对工具路径。AI 助手说完成后，也要实际启动验证。</p>"),e("issue-voice","语音有结果，却没有回填","<p>先复制保留的识别文字，避免重说。之后检查目标输入框焦点、系统权限与快捷键冲突。macOS 关注辅助功能权限；Linux/Wayland 按桌面实际支持的桥接能力处理。</p>"),e("issue-pets","用了很多 Token，TokenPet 没变化","<p>宠物根据智能接入账本的新增记录入账，不覆盖所有网页或第三方客户端消费。先确认「记录统计」已开启、请求经过智能接入，且上游响应包含可识别的用量。TokenPet 也不是 API 余额。</p>"),e("issue-help","怎样更高效地反馈",'<p>记录系统与架构、EchoBird 版本、页面和工具名、已经执行的步骤、错误原文，以及你期望的结果。分享截图前隐藏账号与密钥。你可以通过 <a href="https://github.com/edison7009/EchoBird/issues" target="_blank" rel="noopener noreferrer">GitHub Issues</a> 或 <a href="mailto:hi@echobird.ai">hi@echobird.ai</a> 联系我们。</p>')].join("")}],J=[{id:"apps",title:"App Desktop and Store",summary:"Find and install tools, choose a source, then apply your configuration and launch the app.",body:'<section aria-labelledby="desktop"><h2 id="desktop">Apps: keep familiar tools together</h2><p>App Desktop brings together AI clients, CLIs, and related tools. Select an icon to see the accounts and model settings available for that tool on the right. You still use the client you know; EchoBird provides a central place to manage its entry point and supported settings.</p><p>Tools do not all support the same operations. Some can switch official accounts, some accept API model configurations, and others mainly provide a launch entry. Check the options actually shown for the selected tool.</p></section><section aria-labelledby="discover"><h2 id="discover">An installed tool is not detected</h2><ol class="doc-steps"><li>Confirm that the third-party tool has finished installing and can launch normally from your operating system.</li><li>Return to EchoBird and click Refresh to scan for local tools again.</li><li>If it is still missing, open the tool path settings and check the location of its executable.</li><li>Correct the path and refresh again. Do not point to a launcher from another project, or overwrite an existing account configuration simply to make detection succeed.</li></ol></section><section aria-labelledby="install-tools"><h2 id="install-tools">Store: from discovery to installation</h2><p>Store organizes tools that are not installed yet. Select a tool and click Get App to open AI Assistant with an installation request already filled in. Continue the installation based on the assistant’s output and your system environment.</p><aside class="doc-note"><strong>Browsing does not install anything automatically</strong><p>Browsing Store or selecting an icon does not automatically install software. Installation may involve downloads, dependencies, network access, and system permissions. When the assistant finishes, return to App Desktop, refresh detection, and actually launch the tool to verify the result.</p></aside></section><section aria-labelledby="apply"><h2 id="apply">Put an account or model to work in a tool</h2><ol class="doc-steps"><li>Select an installed tool, then choose an official account or an API model. These choices are mutually exclusive, so the client does not receive conflicting identities and endpoints.</li><li>Check the options at the bottom: whether to write configuration and whether to launch at the same time. If you only want to configure the tool, use the options it supports.</li><li>Run the main action and wait for the result. Follow any prompts about a running client or restoring official endpoints.</li><li>Open the client and verify its actual identity and model. A highlight on the right shows your current selection; it does not guarantee that every already-running window switches immediately.</li></ol></section><section aria-labelledby="capabilities"><h2 id="capabilities">Web Search, Image, and 1M</h2><div class="doc-table" data-columns="3"><table><thead><tr><th scope="col">Capability</th><th scope="col">What it configures</th><th scope="col">What to know</th></tr></thead><tbody><tr><td>Web Search</td><td>Web search settings for supported tools</td><td>Also depends on the model and service capabilities</td></tr><tr><td>Image</td><td>Image input settings for supported tools</td><td>Turning it on does not give a text-only model vision capabilities</td></tr><tr><td>1M</td><td>Large-context mode for supported tools</td><td>Actual context length, costs, and limits depend on the tool and service</td></tr></tbody></table></div><p>The pill buttons are independent and can be enabled separately. In the real client, some tools reapply capability settings when a valid API configuration is already selected; these buttons do not always change appearance alone. If a button is absent, follow the capabilities exposed by the current tool.</p></section><section aria-labelledby="result"><h2 id="result">A recommended approach</h2><p>Keep one working official account or model configuration, then establish a clear selection routine for your usual tools. When you need multiple sources and failover, connect the tool to <a href="#smart-access">Smart Routes</a> instead of repeatedly changing endpoint addresses inside each client.</p></section>'},{id:"accounts",title:"Accounts",summary:"Add and manage accounts, and understand plans, quotas, balances, and authorization status.",body:'<section aria-labelledby="account-purpose"><h2 id="account-purpose">Save an account, then decide where to use it</h2><p>Accounts brings together accounts from integrated services and the usage information they provide. A service can have multiple accounts, and one page can manage accounts from different services. Use it to compare status, refresh data, and maintain authorization. Clicking an account card does not by itself switch an external client.</p></section><section aria-labelledby="add-account"><h2 id="add-account">Add your first account</h2><ol class="doc-steps"><li>Find the service in the service list and click Add Account.</li><li>Complete browser sign-in, device-code authorization, client sign-in, or another supported flow as required by the service. Steps and prerequisites vary.</li><li>Wait for EchoBird to save the authorization result. You can cancel while waiting. If the flow times out, start again rather than continuing to wait for the old attempt.</li><li>Confirm the identity shown on the card, then go to App Desktop, select the corresponding app and account, and apply the selection or launch.</li></ol><p>Adding a new login for some services requires their client to be installed locally. Whether an existing account can be refreshed or managed without that client also depends on its integration. Check the current entry’s guidance; you do not need to reinstall every client just to manage saved records.</p></section><section aria-labelledby="read-quota"><h2 id="read-quota">Read quotas and balances correctly</h2><div class="doc-table" data-columns="2"><table><thead><tr><th scope="col">Displayed information</th><th scope="col">How to interpret it</th></tr></thead><tbody><tr><td>Plan</td><td>The account’s subscription or service tier, not its remaining allowance</td></tr><tr><td>5-hour, weekly, or other quotas</td><td>Separate quota periods; read each percentage and reset time individually</td></tr><tr><td>Balance / credits</td><td>The service’s own units, which cannot simply be added to those of other services</td></tr><tr><td>Countdown</td><td>A time reference for the corresponding reset period or service status</td></tr><tr><td>— or unknown</td><td>No usable data is available yet; it means neither zero nor unlimited</td></tr></tbody></table></div><p>Use Refresh when you need current data. Opening the page and explicitly querying a provider are different actions. Expired authorization, network problems, or a provider that does not expose a usage API can all affect the result.</p></section><section aria-labelledby="account-actions"><h2 id="account-actions">Actions on account cards</h2><ul><li><strong>Refresh / Refresh All:</strong> retrieve supported usage information again. This does not switch a client’s account.</li><li><strong>Claim:</strong> appears only when the service offers this capability. Availability and the claim result depend on the account.</li><li><strong>Warm up:</strong> applies only to integrations that provide it; not every account needs warming up.</li><li><strong>Reauthorize:</strong> repeat sign-in when authorization has expired. First distinguish an authorization error from an ordinary quota-query failure.</li><li><strong>Ordering and privacy:</strong> drag frequently used accounts to the front, and hide identities when sharing your screen. Hiding an identity does not remove its authorization.</li><li><strong>Delete:</strong> follow the confirmation flow to remove the saved account record from EchoBird. This does not close the provider account or cancel its subscription.</li></ul></section><section aria-labelledby="account-example"><h2 id="account-example">A routine for working with multiple accounts</h2><p>Before working, refresh your usual accounts and check the correct quota periods separately. In App Desktop, choose an account for the target tool and apply it. Prepare a separate configuration in Models if you need a backup API. Do not assume subscription allowances from multiple accounts can be pooled for all models.</p></section>'},{id:"models",title:"Models",summary:"Organize API addresses, keys, and model IDs, test the connection, then use the model in your tools.",body:'<section aria-labelledby="model-fields"><h2 id="model-fields">What the four fields mean</h2><div class="doc-table" data-columns="3"><table><thead><tr><th scope="col">Field</th><th scope="col">Purpose</th><th scope="col">Examples and notes</th></tr></thead><tbody><tr><td>Name</td><td>Helps you recognize a configuration</td><td>For example, “Everyday writing” or “Backup coding”; it need not match the model ID</td></tr><tr><td>Endpoint address</td><td>The API endpoint actually provided by the service</td><td>Distinguish OpenAI-compatible, Anthropic-compatible, and regional endpoints</td></tr><tr><td>API Key</td><td>A credential for calling the service</td><td>Obtain it from the provider; it is not your website sign-in password</td></tr><tr><td>Model ID</td><td>The model identifier accepted by the service</td><td>Prefer the model list returned by that service rather than guessing from a product nickname</td></tr></tbody></table></div></section><section aria-labelledby="save-model"><h2 id="save-model">Add and verify a model</h2><ol class="doc-steps"><li>Open Models and choose a service from the provider or relay directory, or enter your own service through the available form.</li><li>Check its region, plan, and protocol version. A company’s subscription endpoint and general API endpoint are not necessarily interchangeable.</li><li>Enter the real address and key. Services that support model discovery can return candidate IDs; for other services, use the IDs in their actual documentation.</li><li>Choose a recognizable name and save. Click Test Latency at the top of Config view to check the endpoint’s connection status and latency.</li><li>Then select a supported tool in App Desktop and apply the configuration, or add it to a Smart Routes scheme. Send a request in the real tool or AI Assistant to verify the model’s reply.</li></ol></section><section aria-labelledby="test-vs-usage"><h2 id="test-vs-usage">Connection tests, replies, and usage answer different questions</h2><p>Test Latency at the top of Config view checks an endpoint’s connection and latency. It is not a chat test, and cannot on its own confirm that the API Key, model ID, or reply content works correctly. To verify a model, send a request in a real tool or AI Assistant. Usage view queries the balance or quota information exposed by the service.</p><p>Actual model requests may be billed under the provider’s rules. A model that replies does not necessarily expose a balance API. Some usage queries need additional settings or authorization, and a failed query does not by itself prove the model is unusable.</p></section><section aria-labelledby="maintain-models"><h2 id="maintain-models">Edit, reorder, and delete</h2><p>Put your usual configurations first and use clear names to distinguish work, everyday, and backup sources. After editing, verify that the address, model ID, and credentials still match, then confirm that the target tool uses the configuration you intended.</p><p>Deleting a local entry does not delete the provider account or remotely revoke its API Key. Replace or revoke a key with the provider, then update the configurations that need it in EchoBird.</p></section><section aria-labelledby="saved-not-applied"><h2 id="saved-not-applied">A common misunderstanding: saving did not change the tool</h2><p>Models is a configuration library. Saving creates the entry; it does not automatically switch every external client to that model. Next, select the tool in App Desktop and apply the configuration, or reference it in Smart Routes and connect the tool to that scheme.</p><p>Compatible endpoints do not imply identical capabilities. Tool calling, image input, context length, and model parameters still require support from the tool, model, and integration adapter.</p></section>'},{id:"smart-access",title:"Smart Routes",summary:"Organize model and account sources, switch models in real time, and keep one stable endpoint for your client.",body:'<p class="doc-lead">Smart Routes keeps model choice in your hands: the client connects to a local endpoint, while you manage the sources, model IDs, and attempt order behind it in EchoBird.</p><section aria-labelledby="routing-model"><h2 id="routing-model">One scheme, an ordered route</h2><p>The numbers in a scheme indicate priority. Requests try sources nearer the front first. If a source is rate-limited, out of quota, or temporarily unavailable, later sources are tried next. Once the cooldown ends, attempts return to priority order.</p><p>This is different from requesting several models simultaneously, and does not pool quotas from different providers. Whether a source is usable and which models it can access still depend on its own authorization, plan, and service capabilities.</p></section><section aria-labelledby="create-route"><h2 id="create-route">Create your first scheme</h2><ol class="doc-steps"><li>Open Smart Routes and choose a source from My Models, Account Access, or Free Models. Configurations already saved in Models can be referenced directly.</li><li>Give the scheme a clear name and check its local port, access key, and model identifier. The port must be available; use the actual address displayed in the current interface.</li><li>Place your usual model first and backup sources later. Dragging to reorder saves automatically and takes effect on the next request; it does not replace the model in the middle of an answer.</li><li>Open a source’s model selector and choose an ID it can actually use. Fetch or refresh the service’s model list first if needed.</li><li>In App Desktop, select a tool that supports model switching, choose this scheme, and apply the configuration.</li><li>Send a real request in the tool, then check the access status and statistics to confirm that the request reached the expected source.</li></ol></section><section aria-labelledby="source-labels"><h2 id="source-labels">Free versus keyless</h2><div class="doc-table" data-columns="3"><table><thead><tr><th scope="col">Label</th><th scope="col">What it means</th><th scope="col">What it does not mean</th></tr></thead><tbody><tr><td>Free</td><td>The specific model option in the directory is marked as free</td><td>Every model from that provider is free, unlimited, or permanently available</td></tr><tr><td>Keyless</td><td>This endpoint does not require you to supply your own API Key</td><td>It has no rate limits or conditions, or suits every task</td></tr><tr><td>Account Access</td><td>Uses the model directory and authorization provided by an account integration</td><td>Any subscription account can call every provider’s models</td></tr></tbody></table></div></section><section aria-labelledby="route-views"><h2 id="route-views">Cards, lists, and the terminal</h2><p>Cards help you inspect sources and select model IDs. Lists make it easier to reorder, enable, or pause entries. The terminal shows grouped request information. If the terminal explicitly identifies its data as illustrative, it does not mean you have already made real requests or incurred charges.</p><p>Removing a source from a scheme removes only that reference; the original model or account remains saved. After deleting a scheme, update any external tool that still points to its old address to use another working endpoint.</p></section><section aria-labelledby="route-endpoints"><h2 id="route-endpoints">Use the OpenAI and Anthropic addresses</h2><p>A scheme provides local OpenAI-compatible and Anthropic-compatible endpoints for different clients. Copy the address and key displayed for the current scheme. Do not guess an address from an example port, or manually change one protocol’s URL suffix into another.</p><aside class="doc-note"><strong>Keep EchoBird running when using a local endpoint</strong><p>After you fully quit EchoBird, the local endpoint is unavailable. Minimizing to the tray is different from quitting. If a tool suddenly cannot connect, first check that EchoBird is still running and that the scheme and port are correct.</p></aside></section><section aria-labelledby="route-workflow"><h2 id="route-workflow">The practical result: keep the endpoint, adjust the sources</h2><p>For example, create an “Everyday coding” scheme for your coding tool: use a preferred model for routine tasks, another available service as backup, and suitable free sources when needed. Adjusting the models and their order centrally is more convenient than repeatedly changing endpoints in each client. Still review important outputs; failover does not guarantee that every model delivers the same quality.</p></section>'},{id:"statistics",title:"Request Statistics",summary:"Inspect calls, completion rates, failover, and response times to diagnose route problems.",body:'<section aria-labelledby="open-statistics"><h2 id="open-statistics">Where to find statistics</h2><p>Open Statistics at the top of Smart Routes. View data for ranges such as today, 7 days, or 14 days, and for all schemes or one specific scheme. Make real requests from a tool first, then return to see what each metric represents.</p></section><section aria-labelledby="statistics-metrics"><h2 id="statistics-metrics">Understand the numbers</h2><div class="doc-table" data-columns="2"><table><thead><tr><th scope="col">Metric</th><th scope="col">How to read it</th></tr></thead><tbody><tr><td>Calls</td><td>Requests initiated by clients, not necessarily the number of upstream attempts</td></tr><tr><td>Completion rate</td><td>Calculated from requests with recorded success or failure results</td></tr><tr><td>Successful failover</td><td>A request ultimately succeeded after changing upstream sources; not every attempt necessarily succeeded</td></tr><tr><td>Average duration and trends</td><td>Help compare actual performance over the selected period</td></tr><tr><td>Source distribution and recent usage</td><td>Show which sources handle requests and recent activity</td></tr></tbody></table></div></section><section aria-labelledby="statistics-debug"><h2 id="statistics-debug">Investigate unexpected results</h2><ol class="doc-steps"><li>Check the selected time range and scheme first, so you are not looking for requests in the wrong scope.</li><li>Inspect failed sources and failover results. A preferred source failing before a backup succeeds is different from the entire request failing.</li><li>Return to Smart Routes and check the source’s model ID, enabled state, and priority.</li><li>When needed, explicitly refresh status or test the service in Accounts or Models, then send another request to verify the result.</li></ol></section><section aria-labelledby="statistics-limits"><h2 id="statistics-limits">Statistics are not a bill</h2><p>This page helps you understand requests that pass through the router. It is not a complete statement from every provider or an exact billing system. Missing request records do not mean the account balance is zero, and attempt counts cannot be treated directly as paid-call counts.</p><p>The statistics recording switch in Settings, local storage state, and selected scope all affect the data you can see. Before sharing statistics, you can hide account names to avoid exposing real identities.</p></section>'},{id:"assistant",title:"AI Assistant",summary:"Describe your goal and let the assistant check environments, install tools, or perform real tasks.",body:'<section aria-labelledby="assistant-first"><h2 id="assistant-first">Prepare a working model before starting</h2><ol class="doc-steps"><li>Open AI Assistant. In normal conversation mode, first choose a configured model that works.</li><li>Confirm whether the target is this computer or an SSH server added on the right. The target determines the context for subsequent operations.</li><li>Explain what you want to do, which tool is involved, and the result you expect. Include the specific error if needed.</li><li>After sending, watch the working status, tool calls, and results. Expand tool cards to inspect arguments and output.</li></ol></section><section aria-labelledby="assistant-prompts"><h2 id="assistant-prompts">Requests that work better than “fix this for me”</h2><ul><li>“Check the installation and launch environment for Claude Code on this computer, and tell me what problems you find first.”</li><li>“Help me install Git, then check that it is available in the terminal.”</li><li>“This tool reports the following error when it starts: … Please investigate the cause and explain what you fixed.”</li><li>“Inspect this computer’s hardware and explain what kinds of local models it can run.”</li></ul><p>The assistant chooses steps based on the model, task, and environment. Finding a route, installing a runtime, and configuring PATH in the website animation are examples, not a mandatory pipeline for every task.</p></section><section aria-labelledby="assistant-progress"><h2 id="assistant-progress">Confirm what the assistant actually did</h2><p>AI Assistant can run real commands and operate on files. Tool output can tell you more than the final summary about whether installation finished, which files changed, or whether an error was resolved. After installation, return to App Desktop, refresh detection, and launch the tool to verify it.</p><p>You can stop a running task, but stopping does not undo commands already executed. Not every task prompts for confirmation at every step. Define the goal and permitted scope first, and do not casually paste unknown commands or credentials into the assistant.</p></section><section aria-labelledby="assistant-conversations"><h2 id="assistant-conversations">Conversations and settings for each turn</h2><p>Create, switch, and delete conversations to keep projects or tasks separate. Deleting a conversation requires confirmation, but does not uninstall tools that were installed during it. Settings such as the model and reasoning effort are generally determined when you send a message. A running task uses the settings submitted for that turn; later adjustments mainly affect the next turn.</p></section><section aria-labelledby="assistant-connect"><h2 id="assistant-connect">Connect to an existing agent</h2><p>Connect mode currently supports an installed Claude Code CLI. In this mode, Claude Code handles the turn using its own environment, tools, memory, and model configuration. EchoBird hides its model selector.</p><p>To change that model, manage it in App Desktop or Claude Code’s own settings. Do not assume that model selection in normal assistant mode applies to Connect mode.</p></section><section aria-labelledby="assistant-ssh"><h2 id="assistant-ssh">Run tasks on your own server</h2><p>Add an SSH server on the right by entering its host, port, username, and authentication details. Test the connection before selecting it for a task. The remote machine must already have an accessible SSH service; this feature does not purchase or create a cloud server for you.</p><p>Deleting a server removes only its saved connection entry, not software on the remote machine. Follow the actual prompts when system privileges are needed. Local steps that require a password may be handed over to a native terminal.</p></section>'},{id:"local-models",title:"Local LLM",summary:"Download or scan model files, prepare a runtime engine, then start your own model service.",body:'<section aria-labelledby="local-entry"><h2 id="local-entry">Understand model files and engines first</h2><p>Local LLM manages model files, inference engines, and service processes. It is included in the full edition and controlled by the optional-page switch in Settings.</p><p>Model files contain the weights. The runtime engine loads them and provides a service. Finishing a download does not mean the service has started, and installing an engine does not mean a model has been downloaded. GGUF is a common format for local model files.</p></section><section aria-labelledby="local-run"><h2 id="local-run">Start with your first local model</h2><ol class="doc-steps"><li>In Store, review the models and hardware guidance, and choose a quantized version suited to your machine. If you already have files, add a local model directory and scan it.</li><li>Choose a runtime, detect the corresponding engine, and install it. Use the available controls to select a version or upgrade when needed.</li><li>Select the model, port, compute resources, and context length. Start with conservative settings, then adjust model size and context once the basic setup works.</li><li>Click Start, wait for output, and check the service status, address, and access key. If it fails, read the logs first rather than repeatedly starting it.</li><li>Once the service works, use it through AI Assistant or another supported model entry.</li><li>Click Stop when you are done to release resources used by the service. Leaving the page does not stop the service.</li></ol></section><section aria-labelledby="local-platform"><h2 id="local-platform">Choose a runtime for your system</h2><div class="doc-table" data-columns="2"><table><thead><tr><th scope="col">Runtime path</th><th scope="col">When it applies</th></tr></thead><tbody><tr><td>llama.cpp</td><td>The basic runtime path on all three platforms; performance depends on the hardware and build</td></tr><tr><td>macOS Metal</td><td>Can use acceleration on supported Apple hardware</td></tr><tr><td>NVIDIA CUDA</td><td>Requires a supported NVIDIA environment and a corresponding build</td></tr><tr><td>CPU</td><td>A basic option without a suitable GPU; speed depends on the model and hardware</td></tr><tr><td>vLLM / SGLang</td><td>The current interface offers these options only on Linux when an NVIDIA or AMD GPU is detected</td></tr></tbody></table></div><p>Larger models and longer contexts generally need more memory. Allow room for your operating system and other work applications rather than judging requirements by the model file size alone.</p></section><section aria-labelledby="local-files"><h2 id="local-files">Directories, models, and custom commands</h2><p>Removing a scan directory only removes it from the directory list; it does not delete model files from disk. You can scan again after a download finishes.</p><p>Advanced users can set a custom engine path and launch arguments. When starting out, keep a working default setup. Do not change unfamiliar arguments, ports, and model formats all at once, or it becomes difficult to identify the cause of a failure.</p></section><section aria-labelledby="local-use"><h2 id="local-use">Use it with AI Assistant</h2><p>Confirm the local service works first, then choose an available model source in the assistant. Verify model serving and task execution separately: if a model is missing, check its files and scanning; if a connection fails, check the process, port, and key; if memory is insufficient, reduce the model size or context.</p><p>Running inference locally does not make every task offline. The assistant may still access the network when downloading dependencies, visiting web pages, or calling external services.</p></section>'}],X=[{id:"voice",title:"Voice input and text selection",summary:"Set up recognition channels, a microphone and shortcuts to dictate into your input field.",body:'<section aria-labelledby="voice-setup"><h2 id="voice-setup">Get one speech channel working first</h2><ol class="doc-steps"><li>Open Voice input and add a supported account source, or configure a separate speech-recognition API model. An ordinary chat model does not necessarily support speech recognition.</li><li>Check the speech API URL, model and authorization. You can configure up to three different channels: the first is primary and the others are backups. Drag them to change their order.</li><li>Select the default microphone or a specific device, run the test, and check that the level changes as you speak. Stop the test when you finish.</li><li>Try recognizing a short sentence first. Once the text looks right, set a shortcut that does not conflict with your usual software.</li></ol></section><section aria-labelledby="voice-use"><h2 id="voice-use">Use it in the input field where you are working</h2><ol class="doc-steps"><li>First place the cursor in a chat box, editor or another text input field.</li><li>Start recording with the microphone control or a shortcut. Shortcuts support both hold-to-talk and toggle modes.</li><li>After you stop recording, wait for recognition and insertion to finish. Check the inserted text before deciding whether to send it.</li><li>If focus changes or the system prevents insertion, copy the retained transcription and paste it manually. You can also replay the recording when needed.</li></ol></section><section aria-labelledby="voice-island"><h2 id="voice-island">What the Voice Island shows</h2><p>The Voice Island shows recording, recognition, insertion and completion states. Adjust its theme, colors and size to suit your desktop. It serves a different purpose from the Usage Island: the Voice Island follows the input process, while the Usage Island shows account and model usage.</p></section><section aria-labelledby="selection"><h2 id="selection">Translate or ask about selected text</h2><p>Configure an available text model first, then enable selection translation or questions. After selecting text, start an action near the selection and choose the target translation language. Each selection is limited to 16,000 characters; split longer text into sections.</p><p>If the system cannot retrieve the selection, copy it first and use Paste and translate. The original text is retained if an attempt fails, so you can retry. Without a configured text model, a translation will not appear automatically.</p></section><section aria-labelledby="voice-permissions"><h2 id="voice-permissions">No sound, an inactive shortcut or failed text insertion</h2><ul><li>No microphone level: check the selected device, system input volume and microphone permissions first.</li><li>Shortcut not working: check for key conflicts and system keyboard-monitoring permissions. Text insertion on macOS may also require Accessibility permission.</li><li>Linux / Wayland: shortcuts, text selection and insertion depend on your desktop’s portal or bridge support. Configure them for your actual environment.</li><li>Recognition request failed: check the channel’s service type, URL, credentials and network connection. A remote speech API does not provide fully offline recognition.</li></ul></section><section aria-labelledby="voice-workflow"><h2 id="voice-workflow">A useful combination</h2><p>Place the cursor in the AI Assistant input field, dictate the full task, and check the transcription before sending it. When reading material in another language, translate a selection first, then give the assistant a request you understand. Voice input reduces typing; reviewing the text before sending still helps prevent recognition errors from changing your intent.</p></section>'},{id:"usage-island",title:"Usage Island",summary:"Keep usage on your desktop and choose from five layouts to suit the way you work.",body:'<section aria-labelledby="island-purpose"><h2 id="island-purpose">What information belongs on your desktop</h2><p>The Usage Island puts remaining account quotas, reset countdowns or API model balances into a small floating desktop window. Glance at it while working instead of repeatedly returning to a management page. It displays status; it does not increase quotas or automatically switch accounts for every tool.</p></section><section aria-labelledby="island-setup"><h2 id="island-setup">First-time setup</h2><ol class="doc-steps"><li>Open Usage Island at the top of App Desktop. Prepare available sources in Account Center or Model Center first.</li><li>Choose the accounts or models to display, up to six. Start with the sources you use most or whose quotas run out most easily.</li><li>Choose a layout and expansion direction, then select hover, click-to-expand or always-open behavior.</li><li>Adjust the theme, size and opacity for your desktop background, then enable the Usage Island.</li><li>Refresh manually when you need new data, or choose a refresh interval that suits your needs.</li></ol></section><section aria-labelledby="island-shapes"><h2 id="island-shapes">Choosing among the five layouts</h2><div class="doc-table" data-columns="3"><table><thead><tr><th scope="col">Layout</th><th scope="col">Where it fits</th><th scope="col">Expansion direction</th></tr></thead><tbody><tr><td>Horizontal</td><td>Along a screen edge or in a wider open area</td><td>Left / Right</td></tr><tr><td>Vertical</td><td>In a narrow area at the side</td><td>Up / Down</td></tr><tr><td>Dial</td><td>A compact view of several sources</td><td>Clockwise / Counterclockwise</td></tr><tr><td>List</td><td>For reading each status individually</td><td>Information arranged as a list</td></tr><tr><td>Lines</td><td>A horizontal overview with a small footprint</td><td>Expands in the selected direction</td></tr></tbody></table></div><p>Layout and direction change presentation only. They do not change account permissions, model capabilities or routing priority.</p></section><section aria-labelledby="island-controls"><h2 id="island-controls">Theme, size, opacity and refresh</h2><p>Themes include the theme color, dark, light and system-following options. Size ranges from 70% to 150%, and opacity from 20% to 100%. If the text is too small, increase the size first, then adjust its position.</p><p>Refresh is manual by default. You can also choose 5, 15, 30 or 60 minutes. Whether a source supports refreshing, and which fields it provides, depends on that integration. An unknown value must not be treated as a zero balance.</p><p>Enable Smart Routes status to observe current access activity. This is a status display, not an additional route.</p></section><section aria-labelledby="island-scenario"><h2 id="island-scenario">Use it with Smart Routes</h2><p>Set up your everyday access configuration first, then add your usual accounts or models to the Usage Island. When a quota is nearly exhausted, return to the relevant page to refresh and check it before changing sources or priorities. The Usage Island flags states that need attention; actual account and model application remains on the corresponding management pages.</p></section>'},{id:"pets",title:"Pets and TokenPet",summary:"Turn tokens recorded through Smart Routes into pet growth, and learn about hatching, leveling up and supplies.",body:'<section aria-labelledby="pet-entry"><h2 id="pet-entry">Start with a pet</h2><p>Open Pets at the top of App Desktop. Six voxel pets are currently available in different colors: Iron Bean, Rainbow unicorn, Spined kaiju, Nine-tailed fox, Alien and Mr. Kangaroo. Select a pet, drag to rotate it, or adjust the viewing angle with the arrow keys.</p><p>TokenPet is a growth unit within the pet system. It is not an API balance, cannot be cashed out, and does not add usable quota with a provider.</p></section><section aria-labelledby="tokenpet-source"><h2 id="tokenpet-source">Where TokenPet comes from</h2><p>The system uses cumulative token consumption recorded in the Smart Routes ledger and credits only the increase to your pet growth balance, preventing the same cumulative usage from being credited twice. Enable Record statistics in Settings, and make sure upstream responses provide recognizable usage data.</p><aside class="doc-note"><strong>Only recorded access usage counts</strong><p>Consumption across all your websites, third-party tools and accounts is not automatically monitored or converted. Usage that does not pass through Smart Routes, or has no corresponding usable record, may not generate TokenPet. You do not need to spend extra model tokens to complete the beginner tutorial.</p></aside></section><section aria-labelledby="pet-grow"><h2 id="pet-grow">How to hatch and level up</h2><ol class="doc-steps"><li>Check your TokenPet balance and select the pet you want to raise.</li><li>Click Level up to put the available balance toward growth. If it is not enough for a full level, experience can accumulate within the current level.</li><li>Wait for leveling and stage animations to finish before taking the next action. Watch the pet progress from an egg and cracked shell to a baby and adult.</li><li>To raise more pets, buy a new egg at the price shown on the page. An egg currently costs 100 million TokenPet; use the displayed price and upgrade cost as your reference.</li></ol></section><section aria-labelledby="pet-stages"><h2 id="pet-stages">Growth stages</h2><div class="doc-table" data-columns="2"><table><thead><tr><th scope="col">Level</th><th scope="col">Form</th></tr></thead><tbody><tr><td>0–9</td><td>Whole egg</td></tr><tr><td>10–19</td><td>Cracked egg</td></tr><tr><td>20–29</td><td>Baby</td></tr><tr><td>30–49</td><td>Young</td></tr><tr><td>50–60</td><td>Adult; the current maximum level is 60</td></tr></tbody></table></div></section><section aria-labelledby="pet-rewards"><h2 id="pet-rewards">What pet supplies do</h2><ul><li><strong>Growth card:</strong>Adds TokenPet within the pet system.</li><li><strong>Double card:</strong>Affects growth-card rewards for 15 minutes at present; it does not double model quota.</li><li><strong>Haste card:</strong>Brings the next supply forward. It does not speed up model inference.</li></ul><p>Check the page’s countdown for eligibility and the next supply time. Pets provide companionship alongside your work; they are not a prerequisite for using applications, models or Smart Routes.</p></section>'},{id:"plugins",title:"Plugins",summary:"Discover and manage extensions, including installation sources, permissions and updates.",body:'<section aria-labelledby="plugin-entry"><h2 id="plugin-entry">What plugins add</h2><p>The Plugins page at the top of App Desktop lets you discover and manage extensions. Plugins can provide application entries, account integrations, appearance options or other features. Installing one is different from installing a third-party AI client: the client is the tool you use, while a plugin adds supported capabilities within EchoBird.</p></section><section aria-labelledby="plugin-find"><h2 id="plugin-find">Find an extension in the catalog</h2><ol class="doc-steps"><li>Open Plugins and browse the catalog or installed items for the extension you need.</li><li>Narrow the results with search or categories such as apps, accounts, appearance and features.</li><li>Switch between international, domestic or CNB sources when needed. If refreshing fails, check the selected source first. The installed list and online catalog are separate sets of data.</li><li>Select an extension and review its name, description, source, version and permissions on the right, then use the installation action provided.</li></ol></section><section aria-labelledby="plugin-import"><h2 id="plugin-import">Add from a repository or local directory</h2><p>The Add menu offers repository and local-directory options. Use a URL or extension directory whose source you have verified. Wait for the candidate extension’s information to be parsed, then read its permissions and complete installation. Not every folder is a valid plugin.</p><p>Account plugins involve authorized access, and model-request permission may let a plugin use models. Clipboard, configuration, storage, command and background capabilities each have their own purposes too. Check permissions against the features you intend to use rather than installing based only on a similar name.</p></section><section aria-labelledby="plugin-manage"><h2 id="plugin-manage">Enable, update and uninstall</h2><p>After installation, enable and use the plugin through the controls it provides. You can check for updates on the right. If an update adds permissions, confirmation is required again; canceling that confirmation does not complete the update.</p><p>Uninstallation requires confirmation. Removing an extension may make its account capabilities or interface entries unavailable. Remaining cached content does not mean the service can still perform operations. If an update fails, check the source, network connection and specific error before retrying.</p></section><section aria-labelledby="plugin-account-use"><h2 id="plugin-account-use">The account service you want is missing</h2><p>Check whether the service is provided through an account plugin and whether that plugin is installed and enabled. Then return to Account Center or the relevant tool page. Plugins can add integration methods, but cannot bypass provider login, permissions or subscription restrictions.</p></section>'},{id:"news",title:"AI Latest News",summary:"Read news by date in one place and open the original article when needed.",body:'<section aria-labelledby="news-read"><h2 id="news-read">Read news for a selected date</h2><ol class="doc-steps"><li>Open AI Latest News from the sidebar and wait for the content to load.</li><li>The Simplified Chinese interface can switch between domestic and global sources. Other interface languages use global sources.</li><li>Select a date in the date tree on the right. The list shows content for that date.</li><li>Review titles, sources and relative timestamps, then click an item to open the original article.</li></ol></section><section aria-labelledby="news-refresh"><h2 id="news-refresh">Refreshing and cached history</h2><p>Use Refresh when you want new content. Existing cached items are retained if the network fails, so there is no need to clear your history or reinstall just to reload. When looking at older content, also check the current source and date before assuming that all historical data is gone.</p></section><section aria-labelledby="news-purpose"><h2 id="news-purpose">Keep reading separate from execution</h2><p>AI Latest News brings news together; the original content and opinions come from the respective sources. If you discover a new tool, check whether it is listed in App Desktop. Before trying it, review its actual system requirements and official instructions. Reading news does not automatically install tools or make the assistant execute commands from an article.</p><p>If you do not need the news entry, disable AI Latest News in Settings to keep the sidebar simpler.</p></section>'},{id:"career",title:"My AI Career",summary:"Review local sessions and activity patterns, and find work you can continue.",body:'<section aria-labelledby="career-overview"><h2 id="career-overview">What the overview shows</h2><p>My AI Career organizes local sessions and activity records from supported tools. The overview includes session count, message count, approximate cumulative tokens, active days and longest streak, with a contribution heatmap and daily activity chart to show your usage patterns.</p><p>Available fields vary by tool. Token counts include estimates and should not be treated as a provider bill. Missing records do not necessarily mean you have never used a tool.</p></section><section aria-labelledby="career-find"><h2 id="career-find">Find a previous session</h2><ol class="doc-steps"><li>Open My AI Career, wait for local records to load, and begin by reviewing activity by date.</li><li>Select a tool family to view its session list.</li><li>Find the session you need and check its timestamp, content summary and available project path or session information.</li><li>Use the actions available for that tool to copy the session ID, resume command or project path, or locate the record file.</li><li>Return to the corresponding tool to continue working. Resume capabilities are not identical across all tools and sessions.</li></ol></section><section aria-labelledby="career-combine"><h2 id="career-combine">How it fits with other pages</h2><p>App Desktop helps you open tools; My AI Career helps you review your activity in them. To resume work, find the session and project path first, then check the account and model source in App Desktop. This can reduce the need to explain the context again from scratch.</p><p>This page focuses on local sessions and activity records, rather than a shared team task board. A project path is information associated with a session; copying it does not automatically migrate or back up the entire project.</p></section>'}],Z=[{id:"welcome",title:"Meet EchoBird",summary:"Understand apps, accounts, models, and routing groups, then choose the right starting point.",body:'<p class="doc-lead">EchoBird brings AI tools, accounts, and models together on one desktop. Keep using the clients you know, prepare and manage your setup here, and return your attention to what you want to create.</p><section aria-labelledby="what-it-does"><h2 id="what-it-does">Start with these four concepts</h2><div class="doc-table" data-columns="3"><table><thead><tr><th scope="col">Concept</th><th scope="col">Think of it as</th><th scope="col">Where to manage it</th></tr></thead><tbody><tr><td>App / Agent</td><td>The tool that carries out tasks or chats with you, such as a coding client or desktop assistant</td><td>App Desktop</td></tr><tr><td>Account</td><td>Your identity with a provider, together with its plan, authorization, and quota</td><td>Accounts</td></tr><tr><td>Model</td><td>A callable API configuration: endpoint, credentials, and model ID</td><td>Models</td></tr><tr><td>Routing group</td><td>An arrangement of available sources that gives your tools one local endpoint</td><td>Smart Routes</td></tr></tbody></table></div></section><section aria-labelledby="choose-path"><h2 id="choose-path">Choose a starting point</h2><ul><li><strong>Already have an official account? </strong>Detect or install the app, add your account, then select and apply it in App Desktop. This suits users who want to keep using an existing subscription.</li><li><strong>Already have an API key? </strong>Save the configuration and test its connection speed in Models, then verify actual replies in a supported tool. This suits users who want to reuse an API service.</li><li><strong>Have several model sources? </strong>Arrange primary and fallback sources in Smart Routes so your tools can use one endpoint.</li><li><strong>Want to use your own hardware? </strong>Start a service in Local LLM, then let other supported features use it.</li></ul></section><section aria-labelledby="what-is-different"><h2 id="what-is-different">Managing, selecting, and applying are separate steps</h2><p>Saving an account or model tells EchoBird to remember it. Selecting an entry indicates what you intend to use. Applying the configuration makes that choice take effect in the corresponding tool. Keeping these steps separate lets you maintain multiple configurations centrally without changing a working client just by browsing a page.</p><aside class="doc-note"><strong>Get one tool working first</strong><p>For your first setup, choose one tool you already know. Complete the full sequence—save a source, select the tool, apply the configuration, and make a real request—before adding more accounts, fallback models, or desktop features.</p></aside></section><section aria-labelledby="page-map"><h2 id="page-map">How the features fit together</h2><p>App Desktop is your starting point. Accounts and Models provide available sources, Smart Routes organizes them, and AI Assistant carries out the tasks you describe. Voice Input reduces typing, Usage Island keeps status on your desktop, and TokenPet adds companionship to your work. News, My AI Career, and Local LLM can be enabled as needed.</p><p>Read <a href="#quick-start">Quick Start</a> first. If your sources are already configured, go straight to <a href="#workflows">Workflow Guides</a>.</p></section>'},{id:"quick-start",title:"Quick Start",summary:"Go from installing EchoBird to making your first tool work.",body:`<section aria-labelledby="install"><h2 id="install">Install and open EchoBird</h2><ol class="doc-steps"><li>Choose an installer from the <a href="./#download">official download area</a> that matches your operating system and processor. Windows, macOS, and Linux packages are not interchangeable.</li><li>Complete the system installation process and open EchoBird. On your first launch, check App Desktop to see which tools have been detected.</li><li>If an installed tool is missing, click Refresh, then use the tool-path settings to check the executable location.</li></ol></section><section aria-labelledby="prepare-source"><h2 id="prepare-source">Prepare one working source</h2><p>Choose either of the following routes. You do not need to configure both an account and an API to get started.</p><div class="doc-table" data-columns="3"><table><thead><tr><th scope="col">What you have</th><th scope="col">Next step</th><th scope="col">Where to go afterward</th></tr></thead><tbody><tr><td>An official account with a supported service</td><td>Open Accounts, add the account, and complete the service's authorization process</td><td>Select the corresponding tool and account in App Desktop</td></tr><tr><td>An API key from a provider</td><td>Open Models, enter the real endpoint and model ID, save, and click Test Latency</td><td>Select a tool in App Desktop that supports this model configuration</td></tr></tbody></table></div><p>A web chat account password is not an API key. Domestic, international, subscription, and other service endpoints from the same provider may also require different credentials.</p></section><section aria-labelledby="first-launch"><h2 id="first-launch">Apply your first configuration and launch</h2><ol class="doc-steps"><li>Select an installed tool in App Desktop. The right panel shows the account or model options supported by that tool.</li><li>Select the source you just saved. Official accounts and API models are mutually exclusive: selecting one clears the other selection.</li><li>Read the current main action at the bottom and the launch/configuration-write options, then apply or launch as appropriate. The actual client's buttons change with the situation.</li><li>In the opened tool, check the active identity or model and send a simple request, such as “Briefly introduce what you can do.”</li></ol></section><section aria-labelledby="verify"><h2 id="verify">How to confirm the setup works</h2><ul><li>The tool opens normally and a real request receives a normal reply.</li><li>When using an official account, the identity shown in the tool is the account you intended.</li><li>When using an API, the endpoint, model ID, and credentials match. If routing is involved, the local routing endpoint is available.</li><li>Keep the exact error if something fails. Authorization, model IDs, protocols, networking, and installation paths are different issues and should be checked separately.</li></ul></section><section aria-labelledby="next"><h2 id="next">What to try next</h2><p>To reuse configurations across tools, read <a href="#models">Models</a>. For fallback sources, read <a href="#smart-access">Smart Routes</a>. To reduce manual installation work, read <a href="#assistant">AI Assistant</a>. If your tool already works, keep that successful configuration and add features gradually.</p></section>`},{id:"navigation",title:"Interface and Navigation",summary:"Understand the left sidebar, the entries at the top of App Desktop, and each page’s main workspace.",body:`<section aria-labelledby="main-navigation"><h2 id="main-navigation">Use the left sidebar to switch workspaces</h2><div class="doc-table" data-columns="2"><table><thead><tr><th scope="col">Page</th><th scope="col">The question it helps answer</th></tr></thead><tbody><tr><td>App Desktop</td><td>Which tool should I open, and which source should it use?</td></tr><tr><td>Models</td><td>Which reusable API services and model configurations do I have?</td></tr><tr><td>Accounts</td><td>What is the status of my accounts, plans, and quotas?</td></tr><tr><td>Smart Routes</td><td>How should I organize model sources and fallback priorities for my tools?</td></tr><tr><td>Voice Input</td><td>How do I configure recording, recognition, and text processing?</td></tr><tr><td>AI Assistant</td><td>Can I describe a goal and let the assistant carry it out?</td></tr><tr><td>News / My AI Career / Local LLM</td><td>Additional workspaces you can enable as needed</td></tr></tbody></table></div></section><section aria-labelledby="desktop-tabs"><h2 id="desktop-tabs">Other entries at the top of App Desktop</h2><p>My shows your app entries, while Store lets you browse tools that are not installed. Pets, Plugins, and Usage Island at the top manage TokenPet, extensions, and desktop usage displays respectively. You do not need to find an app icon with the same name first.</p><p>Smart Routes's Configuration and Statistics views also have separate roles: one organizes sources, while the other shows request outcomes and trends.</p></section><section aria-labelledby="panels"><h2 id="panels">Understanding the main area, right panel, and bottom action</h2><ul><li><strong>Main area: </strong>Shows the current page's apps, models, accounts, conversations, or settings.</li><li><strong>Right panel: </strong>Provides configuration, sources, targets, or details for the current selection. Its controls may change when you select another tool.</li><li><strong>Main action at the bottom: </strong>Applies the current selection as a configuration, launch, or installation request. Read the button and options before proceeding.</li><li><strong>Back and Forward: </strong>Return to previously visited locations. They do not undo configurations, commands, or installations that have already run.</li></ul></section><section aria-labelledby="missing-page"><h2 id="missing-page">If you cannot find a page</h2><p>Open Settings at the lower left and check whether the optional page is enabled. Local LLM also depends on the capabilities included in your edition. If a tool has no account section, Image button, or 1M button, it generally does not expose that capability; it does not mean the feature is missing everywhere.</p><p>Pages and buttons may differ from the interactive demo on the website homepage. The demo uses sample data and simplified flows; follow the current client interface for real operations.</p></section>`},{id:"settings",title:"Settings and Personalization",summary:"Adjust the interface, language, optional pages, and everyday app behavior.",body:`<section aria-labelledby="settings-entry"><h2 id="settings-entry">Where to open Settings</h2><p>Use Settings at the bottom of the sidebar. Settings are organized into General, Appearance, and Language. Before changing anything, distinguish app-wide settings from the settings for an individual feature.</p></section><section aria-labelledby="settings-general"><h2 id="settings-general">General settings</h2><div class="doc-table" data-columns="2"><table><thead><tr><th scope="col">Setting</th><th scope="col">Purpose</th></tr></thead><tbody><tr><td>UI scale</td><td>Adjust interface size for your screen and reading preferences; try automatic scaling first</td></tr><tr><td>When closing the window</td><td>Choose to exit, minimize to the system tray, or ask each time</td></tr><tr><td>Launch at startup</td><td>Control whether EchoBird opens when you sign in to your system</td></tr><tr><td>Auto-claim rewards</td><td>Manage supported automatic claiming; not every service offers rewards</td></tr><tr><td>Sensitive information protection</td><td>Identify and strengthen protection for keys, tokens, passwords, and similar information when using Smart Routes; related mappings are saved locally</td></tr><tr><td>Record statistics</td><td>Control statistics recording; this does not stop a running model service</td></tr><tr><td>Optional pages</td><td>Show AI Latest News, My AI Career, and Local LLM as needed</td></tr></tbody></table></div></section><section aria-labelledby="settings-appearance"><h2 id="settings-appearance">Appearance and backgrounds</h2><p>Choose a color palette and Light, Dark, or Follow System mode. Background options include None, Character Flow, Carbon Fiber, and Basalt, so you can match your desktop and reading preferences. If text is too small, adjust UI scale before changing your screen resolution.</p><p>Usage Island and Voice Island also have their own theme and size settings. Changing the main window's appearance does not automatically set every parameter in those features to the same value.</p></section><section aria-labelledby="settings-language"><h2 id="settings-language">Language</h2><p>The current choices are English, Simplified Chinese, Traditional Chinese, and Japanese. Check the interface after selecting a language. Model IDs, errors returned by providers, and third-party content may remain in their original language; do not alter a model ID merely to translate it.</p></section><section aria-labelledby="settings-optional"><h2 id="settings-optional">Check here when an entry is missing</h2><p>If you do not need news or activity history, disable the corresponding page; you can enable it again later. Local LLM also depends on whether your installed edition includes that capability.</p><p>Desktop activation and sources for Usage Island are managed on the Usage Island page. Voice Input needs a working channel first. Page visibility, feature activation, and service running status are separate controls.</p></section>`},{id:"workflows",title:"Workflow Guides",summary:"Connect individual pages into useful workflows and understand what each step achieves.",body:`<section aria-labelledby="workflow-account"><h2 id="workflow-account">Route 1: Keep using your subscription</h2><ol class="doc-steps"><li><strong>App Desktop: </strong>Detect or install the client you normally use.</li><li><strong>Accounts: </strong>Add your official account and check its identity and authorization.</li><li><strong>App Desktop: </strong>Select the client and account, then apply the configuration and launch.</li><li><strong>The actual client: </strong>Check the identity and make a request. Return to Accounts to refresh quota when needed.</li></ol><p><strong>Result: </strong>Manage account status centrally while using familiar tools. Adding an account and switching a client remain clearly separate steps.</p></section><section aria-labelledby="workflow-api"><h2 id="workflow-api">Route 2: Reuse a model across tools</h2><ol class="doc-steps"><li><strong>Models: </strong>Save the endpoint, key, and model ID, then click Test Latency to check connectivity and latency.</li><li><strong>App Desktop: </strong>Select this model for a supported tool and apply its configuration.</li><li><strong>A second tool: </strong>Reuse the same model entry, applying it with a protocol that tool supports.</li><li><strong>Verify: </strong>Make a request in each tool to confirm the configuration has taken effect beyond simply being saved in EchoBird.</li></ol><p><strong>Result: </strong>Less repeated data entry and a clear record of your model sources. Protocol and feature support still depend on each tool and model.</p></section><section aria-labelledby="workflow-route"><h2 id="workflow-route">Route 3: Primary models and fallback sources</h2><ol class="doc-steps"><li>Verify your primary and fallback APIs in Models. You can also prepare supported account sources.</li><li>Create a group in Smart Routes, configure the actual endpoint and key, and arrange sources by priority.</li><li>Connect your coding client to that group and make a real request.</li><li>Review completion and failover results in Statistics, and add your usual usage sources to Usage Island.</li></ol><p><strong>Result: </strong>Keep the client's connection relatively stable while adjusting sources centrally. When quotas or failures change, status information helps you decide what to do next instead of blindly repeating requests.</p></section><section aria-labelledby="workflow-install"><h2 id="workflow-install">Route 4: From an error back to work</h2><ol class="doc-steps"><li>Check installation status in App Desktop and keep the exact error if a tool cannot launch.</li><li>Open AI Assistant and describe the tool, operating system, error, and desired result.</li><li>Watch the environment checks and tool output, handling permissions through system prompts when needed.</li><li>Return to App Desktop, refresh detection, and launch the tool to confirm the issue is resolved.</li></ol><p><strong>Result: </strong>Connect installation troubleshooting with a real acceptance check. The assistant's summary explains the process; a successful launch confirms the outcome.</p></section><section aria-labelledby="workflow-voice"><h2 id="workflow-voice">Route 5: Speak your request and stay focused</h2><p>Configure a channel in Voice Input and test the microphone, then place the cursor in AI Assistant or your usual tool. Dictate the task, check the recognized text, and send it. Monitor status with Usage Island as you work. Tokens recorded through Smart Routes can also contribute to pet growth on the Pets page.</p></section><section aria-labelledby="workflow-local"><h2 id="workflow-local">Route 6: Your hardware, your model service</h2><p>Prepare model files and an engine in Local LLM, start the service, and then let supported model entries and AI Assistant use it. If something fails, distinguish a service that has not started, an unavailable model, and a failed task. This lets you verify “running the model” separately from “having the model do something.”</p></section>`},{id:"support",title:"Feedback and Release Notes",summary:"Gather useful details, choose a feedback channel, and learn what changed in each release.",body:`<section aria-labelledby="support-entry"><h2 id="support-entry">Open Feedback</h2><p>Click Feedback in the client's title bar or open the corresponding page from the system menu. This page helps you prepare information and choose an external submission channel; it is not a ticket form that automatically uploads everything.</p></section><section aria-labelledby="support-submit"><h2 id="support-submit">Report a problem</h2><ol class="doc-steps"><li>Record your operating system and architecture, EchoBird version, page and tool names, and the steps that trigger the problem.</li><li>When troubleshooting an error, click the button to copy the latest 30 log entries. Copying does not send them; you still need to paste the logs into your report.</li><li>Use the GitHub entry on the page to create an issue. The Simplified Chinese interface also provides a Gitcode feedback entry.</li><li>Describe the expected and actual results, attach relevant screenshots or logs, and check for accounts, keys, or other sensitive information before submitting.</li></ol><p>Other interface languages also provide an email button that copies hi@echobird.ai. It does not send a message automatically. Continue in your own email app to contact us.</p></section><section aria-labelledby="support-suggest"><h2 id="support-suggest">Suggest an app or improvement</h2><p>You can use the same external feedback entries to describe a tool you would like supported or a workflow you want improved. Include the tool's name, official website, use case, and the steps you currently perform manually. This is more useful than simply asking for support. You do not need to copy error logs before submitting a feature suggestion.</p></section><section aria-labelledby="changelog"><h2 id="changelog">Release notes and installing updates are different</h2><p>Release Notes in the title bar opens a dialog with the version, release date, and changes in the corresponding language. The dialog may also open once after a first installation or an upgrade to a version whose notes you have not read.</p><p>Opening release notes does not immediately install an update. To update the software, continue through the client's download or installation entry. If the notes fail to load, try again later; already loaded content is retained where possible.</p></section>`},{id:"troubleshooting",title:"Troubleshooting",summary:"Identify the layer where a problem occurs, then check the relevant settings.",body:`<section aria-labelledby="issue-account"><h2 id="issue-account">The account was added, but the client did not switch</h2><p>Adding an account only saves it. Return to App Desktop, select the corresponding client and account, run the current main action, and check whether the running client needs further attention. A highlighted selection alone does not mean every open window has switched.</p></section><section aria-labelledby="issue-model"><h2 id="issue-model">The model was saved, but the tool still uses the old model</h2><p>Check whether you applied the model in App Desktop, whether the tool supports its protocol, and whether configuration-write options allow the change. First click Test Latency in Models to check connectivity, then send a request in the actual tool or AI Assistant to verify the reply and active configuration. This is more useful than repeatedly saving the same entry.</p></section><section aria-labelledby="issue-network"><h2 id="issue-network">The model cannot connect or a routed request fails</h2><ol class="doc-steps"><li>Direct model: check the endpoint, key, model ID, and the service's regional or plan-specific entry.</li><li>Smart Routes: confirm EchoBird is still running and the tool uses the endpoint and key shown by the current group.</li><li>Check source authorization, enabled status, and the model catalog. Distinguish a single upstream failure from failure of the overall request.</li><li>Explicitly test or refresh on the relevant page, then make another real request. Keep the original error message.</li></ol></section><section aria-labelledby="issue-quota"><h2 id="issue-quota">Why is the balance or quota blank?</h2><p>A service may answer requests without providing a usage-query API. Some sources need additional usage configuration, and some expose only certain metrics. Refresh explicitly and check authorization and service documentation. An unknown value does not mean zero. Different periods and units also cannot simply be added together.</p></section><section aria-labelledby="issue-install"><h2 id="issue-install">Installation failed or a tool was not detected</h2><p>First confirm the vendor supports your operating system and architecture, then check the network, permissions, dependencies, and installation output. After installation, return to App Desktop and refresh. If the tool is still missing, check its executable path. Even if AI Assistant reports completion, launch the tool to verify it.</p></section><section aria-labelledby="issue-voice"><h2 id="issue-voice">Speech was recognized, but the text was not inserted</h2><p>Copy the retained recognition result first so you do not have to repeat yourself. Then check input focus, system permissions, and shortcut conflicts. On macOS, check Accessibility permissions. On Linux/Wayland, follow the bridging capabilities actually supported by your desktop.</p></section><section aria-labelledby="issue-pets"><h2 id="issue-pets">I used many tokens, but TokenPet did not change</h2><p>Pet credit comes from new records in the Smart Routes ledger, not all consumption in websites or third-party clients. Confirm Record Statistics is enabled, requests pass through Smart Routes, and upstream responses contain recognizable usage data. TokenPet is not an API balance.</p></section><section aria-labelledby="issue-help"><h2 id="issue-help">How to send a useful report</h2><p>Include your operating system and architecture, EchoBird version, page and tool names, the steps you performed, the original error, and your expected result. Hide accounts and keys before sharing screenshots. Contact us through <a href="https://github.com/edison7009/EchoBird/issues" target="_blank" rel="noopener noreferrer">GitHub Issues</a> or <a href="mailto:hi@echobird.ai">hi@echobird.ai</a>.</p></section>`}],ee=new Map([...J,...X,...Z].map(t=>[t.id,t]));function te(t="zh"){return Q.map(o=>t==="en"?{...o,...ee.get(o.id)}:o)}function R(t="zh"){const o=te(t);return H.flatMap(n=>o.filter(a=>a.group===n))}function oe(t,o){return t.replace(/href="#([^"/]+)(?:\/([^"]+))?"/g,(n,a,s)=>`href="${w(o,a)}${s?`#${s}`:""}"`).replace(/href="\.\/#download"/g,`href="${K(o)}#download"`)}R("zh");const T=t=>String(t).normalize("NFKC").toLowerCase().replace(/\s+/g,""),ae=t=>t.replace(/<[^>]+>/g," ").replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/\s+/g," ").trim();function ne(t,o="zh",n=""){const a=V(n,t),[s,r]=String(t).replace(/^#/,"").split("/"),d=a.locale&&a.page==="docs"?a.article:s,u=a.locale&&a.page==="docs"?a.heading:r,f=R(o),y=f.find(S=>S.id===d)??f[0],m=y.id===d&&u?u:null;return{article:y,heading:m}}func